package com.example.data

object MarkData {
    val verses: List<Verse> = listOf(
        Verse(book = "Mak", chapter = 1, verseNumber = 1, text = "Men konmansman Bon Nouvèl ki pale sou Jezikri, Pitit Bondye a.", bookId = 41),
        Verse(book = "Mak", chapter = 1, verseNumber = 2, text = "Nan liv pwofèt Ezayi a, men sa ki te ekri: Bondye di: Men m'ap voye mesaje m' lan devan ou. La louvri chemen an pou ou.", bookId = 41),
        Verse(book = "Mak", chapter = 1, verseNumber = 3, text = "Se vwa yon nonm k'ap rele nan dezè a: Pare gran wout Seyè nou an. Plani chemen an byen plani pou li.", bookId = 41),
        Verse(book = "Mak", chapter = 1, verseNumber = 4, text = "Se konsa Jan te parèt nan dezè a, li t'ap batize, li t'ap mache bay mesaj sa a: -Tounen vin jwenn Bondye. vin resevwa batèm, epi Bondye va padonnen peche nou yo.", bookId = 41),
        Verse(book = "Mak", chapter = 1, verseNumber = 5, text = "Tout moun nan peyi Jide a ansanm ak tout pèp lavil Jerizalèm lan te vin jwenn li: yo te konfese peche yo devan tout moun, epi Jan te batize yo nan larivyè Jouden an.", bookId = 41),
        Verse(book = "Mak", chapter = 1, verseNumber = 6, text = "Jan te mete yon rad pwal chamo sou li, ak yon sentiwon an po mare nan ren li. Se krikèt ak gato myèl li te jwenn nan bwa li te manje.", bookId = 41),
        Verse(book = "Mak", chapter = 1, verseNumber = 7, text = "Li t'ap mache bay mesaj sa a: -Moun k'ap vin apre m' lan gen plis pouvwa anpil pase m'. Mwen pa bon ase pou m' ta bese demare sapat ki nan pye li.", bookId = 41),
        Verse(book = "Mak", chapter = 1, verseNumber = 8, text = "Mwen menm, mwen batize nou nan dlo. Men li menm, la batize nou nan Sentespri a.", bookId = 41),
        Verse(book = "Mak", chapter = 1, verseNumber = 9, text = "Menm epòk sa a, Jezi te soti Nazarèt, yon bouk nan peyi Galile. Lè sa a, Jan te batize l' nan larivyè Jouden an.", bookId = 41),
        Verse(book = "Mak", chapter = 1, verseNumber = 10, text = "Antan Jezi t'ap soti nan dlo a, li wè syèl la louvri, epi Lespri Bondye a desann sou li an fòm yon pijon.", bookId = 41),
        Verse(book = "Mak", chapter = 1, verseNumber = 11, text = "Li tande yon vwa ki soti nan syèl la ki di: -Ou se pitit mwen renmen anpil la. Ou fè kè m' kontan anpil.", bookId = 41),
        Verse(book = "Mak", chapter = 1, verseNumber = 12, text = "Touswit apre sa, Lespri Bondye a pouse Jezi al nan dezè a.", bookId = 41),
        Verse(book = "Mak", chapter = 1, verseNumber = 13, text = "Li rete la pandan karant jou, epi se la Satan vin tante l'. Jezi t'ap viv nan mitan bèt bwa yo, epi zanj Bondye yo t'ap okipe li.", bookId = 41),
        Verse(book = "Mak", chapter = 1, verseNumber = 14, text = "Apre yo te fin mete Jan nan prizon, Jezi ale nan peyi Galile pou l' te fè konnen Bon Nouvèl Bondye voye a.", bookId = 41),
        Verse(book = "Mak", chapter = 1, verseNumber = 15, text = "Li t'ap di yo konsa: -Jou a rive. Koulye a, Bondye ki wa nan syèl la ap vin pran pouvwa a nan men li. Tounen vin jwenn Bondye. Asepte Bon Nouvèl la.", bookId = 41),
        Verse(book = "Mak", chapter = 1, verseNumber = 16, text = "Pandan Jezi t'ap mache bò lanmè Galile a, li wè de pechè pwason, Simon ak Andre, frè li a. Yo t'ap voye privye nan lanmè a.", bookId = 41),
        Verse(book = "Mak", chapter = 1, verseNumber = 17, text = "Jezi di yo konsa: -vin jwenn mwen. m'a fè nou tounen pechè moun pito.", bookId = 41),
        Verse(book = "Mak", chapter = 1, verseNumber = 18, text = "Lamenm, yo kite privye yo, y' ale avèk li.", bookId = 41),
        Verse(book = "Mak", chapter = 1, verseNumber = 19, text = "Jezi vanse pi lwen, li wè de pitit gason Zebede yo, Jak ak Jan, frè li. Yo te chita nan kannòt yo a, yo t'ap repare privye yo.", bookId = 41),
        Verse(book = "Mak", chapter = 1, verseNumber = 20, text = "Lamenm, Jezi rele yo. Yo kite Zebede, papa yo, nan kannòt la ansanm ak ouvrye yo. Y' ale avèk Jezi.", bookId = 41),
        Verse(book = "Mak", chapter = 1, verseNumber = 21, text = "Apre sa, Jezi ale ak disip li yo nan yon lavil yo rele Kapènawòm. Jou repo a, Jezi antre nan sinagòg la; li kòmanse moutre moun yo anpil bagay.", bookId = 41),
        Verse(book = "Mak", chapter = 1, verseNumber = 22, text = "Yo te sezi tande sa l' t'ap moutre yo. Se pa t' menm jan avèk dirèktè lalwa yo, paske li te pale ak yo tankou yon moun ki otorize.", bookId = 41),
        Verse(book = "Mak", chapter = 1, verseNumber = 23, text = "Lè sa a, yon nonm ki te gen yon move lespri sou li vin antre nan sinagòg la, li pran rele:", bookId = 41),
        Verse(book = "Mak", chapter = 1, verseNumber = 24, text = "-ey Jezi, moun Nazarèt, kisa nou gen avè ou? Ou vin isit la pou detwi nou? Mwen konnen byen pwòp ki moun ou ye. Ou se moun Bondye chwazi a.", bookId = 41),
        Verse(book = "Mak", chapter = 1, verseNumber = 25, text = "Jezi pale byen fò ak move lespri ki te sou nonm lan, li di li: -Pe la! Soti sou nonm sa a.", bookId = 41),
        Verse(book = "Mak", chapter = 1, verseNumber = 26, text = "Move lespri a souke nonm lan byen souke, li bay yon gwo rèl, epi li soti, li ale.", bookId = 41),
        Verse(book = "Mak", chapter = 1, verseNumber = 27, text = "Tout moun yo te sitèlman sezi, yonn t'ap mande lòt: -Sa sa ye la a menm! Sa se yon lòt bagay l'ap moutre nou la a. Menm move lespri yo, li pase yo lòd ak otorite, yo obeyi li.", bookId = 41),
        Verse(book = "Mak", chapter = 1, verseNumber = 28, text = "Se tout moun ki t'ap nonmen non l' nan peyi Galile a.", bookId = 41),
        Verse(book = "Mak", chapter = 1, verseNumber = 29, text = "Apre sa, yo soti kite sinagòg la, y' ale ansanm ak Jak ak Jan lakay Simon ak Andre.", bookId = 41),
        Verse(book = "Mak", chapter = 1, verseNumber = 30, text = "Bèlmè Simon an te kouche ak lafyèv. Rive Jezi rive lakay la, yo di l' sa.", bookId = 41),
        Verse(book = "Mak", chapter = 1, verseNumber = 31, text = "Lè sa a, li pwoche bò madanm lan, li pran men l', li fè l' leve. Latou, lafyèv la kite l', epi madanm lan resevwa yo.", bookId = 41),
        Verse(book = "Mak", chapter = 1, verseNumber = 32, text = "Aswè, apre solèy fin kouche, yo mennen tout moun malad yo ansanm ak tou sa ki te gen move lespri sou yo bay Jezi.", bookId = 41),
        Verse(book = "Mak", chapter = 1, verseNumber = 33, text = "Tout moun lavil la te sanble devan pòt kay la.", bookId = 41),
        Verse(book = "Mak", chapter = 1, verseNumber = 34, text = "Lè sa a, Jezi te geri anpil moun ki te soufri divès maladi; li te chase anpil move lespri. Men, li pa t' kite move lespri yo pale, paske yo te konnen ki moun li te ye.", bookId = 41),
        Verse(book = "Mak", chapter = 1, verseNumber = 35, text = "Nan granmaten, byen bonè, li pa t' ankò fè klè, Jezi leve, li soti li kite lavil la, li al yon kote ki pa gen moun. La li t'ap lapriyè.", bookId = 41),
        Verse(book = "Mak", chapter = 1, verseNumber = 36, text = "Simon ak lòt zanmi l' yo soti, yo t'ap chache Jezi.", bookId = 41),
        Verse(book = "Mak", chapter = 1, verseNumber = 37, text = "Lè yo jwenn li, yo di l' konsa: -Tout moun ap chache ou wi.", bookId = 41),
        Verse(book = "Mak", chapter = 1, verseNumber = 38, text = "Men li reponn yo: -Ann al yon lòt kote, nan lòt bouk yo nan vwazinaj la. Fòk mwen fè yo konnen mesaj la tou. Se pou sa menm mwen vini.", bookId = 41),
        Verse(book = "Mak", chapter = 1, verseNumber = 39, text = "Se konsa li te ale toupatou nan peyi Galile, li t'ap mache bay mesaj la nan sinagòg yo, li t'ap chase move lespri yo.", bookId = 41),
        Verse(book = "Mak", chapter = 1, verseNumber = 40, text = "Yon nonm ki te gen lalèp vin jwenn Jezi; li tonbe ajenou devan li, li mande l' sekou; li di l' konsa: -Si ou vle, ou kapab geri mwen.", bookId = 41),
        Verse(book = "Mak", chapter = 1, verseNumber = 41, text = "Kè Jezi fè l' mal, li lonje men l', li manyen nonm lan, li di li: -Wi, mwen vle ou geri.", bookId = 41),
        Verse(book = "Mak", chapter = 1, verseNumber = 42, text = "Menm lè a, lalèp la kite l', li geri, li te nan kondisyon pou fè sèvis Bondye.", bookId = 41),
        Verse(book = "Mak", chapter = 1, verseNumber = 43, text = "Apre sa, Jezi voye l' ale, li pase l' lòd byen sevè.", bookId = 41),
        Verse(book = "Mak", chapter = 1, verseNumber = 44, text = "Li di l' konsa: -Piga ou pale sa ak pesonn. Men, al fè prèt la wè ki jan ou ye. Apre sa, wa ofri sa Moyiz te bay lòd pou ofri a. Konsa wa bay tout moun prèv ou geri.", bookId = 41),
        Verse(book = "Mak", chapter = 1, verseNumber = 45, text = "Men, nonm lan pati, li pran mache fè konnen bagay la toupatou. Li sitèlman gaye nouvèl la, Jezi pa t' kapab antre ankò nan okenn lavil pou moun pa t' wè li. Li te pito rete andeyò, kote ki pa gen moun. Men, moun te soti toupatou vin jwenn li.", bookId = 41),
        Verse(book = "Mak", chapter = 2, verseNumber = 1, text = "Kèk jou apre sa, Jezi tounen Kapènawòm. Yo tande li te lakay li.", bookId = 41),
        Verse(book = "Mak", chapter = 2, verseNumber = 2, text = "Te sitèlman gen moun ki te sanble, pa t' gen plas ankò, pa menm devan pòt kay la. Jezi menm t'ap anonse yo pawòl la.", bookId = 41),
        Verse(book = "Mak", chapter = 2, verseNumber = 3, text = "Se lè sa a, yon kolonn moun vin rive, kat ladan yo t'ap pote yon nonm paralize. Yo t'ap mennen l' bay Jezi.", bookId = 41),
        Verse(book = "Mak", chapter = 2, verseNumber = 4, text = "Men, foul la te kwense anpil, kifè moun yo pa t' ka pwoche bò kot Jezi. Lè yo wè sa, yo dekouvri do kay la egzakteman sou tèt Jezi. Epi yo file nonm paralize a desann nan twou a, tou kouche sou nat li a.", bookId = 41),
        Verse(book = "Mak", chapter = 2, verseNumber = 5, text = "Jezi wè jan yo te gen konfyans nan li, li di nonm paralize a: -Pitit mwen, peche ou yo padonnen.", bookId = 41),
        Verse(book = "Mak", chapter = 2, verseNumber = 6, text = "Te gen kèk dirèktè lalwa chita la; yo t'ap di nan kè yo:", bookId = 41),
        Verse(book = "Mak", chapter = 2, verseNumber = 7, text = "-Pouki nonm sa a pale mal sou Bondye konsa? Ki moun sou latè ki kapab padonnen peche? Sa se travay Bondye sèlman.", bookId = 41),
        Verse(book = "Mak", chapter = 2, verseNumber = 8, text = "Menm lè a Jezi te gen tan konnen nan fon kè l' sak t'ap pase nan tèt yo. Li di yo: -Poukisa n'ap fè lide konsa nan kè nou?", bookId = 41),
        Verse(book = "Mak", chapter = 2, verseNumber = 9, text = "Kisak pi fasil pou m' di nonm paralize a: Peche ou yo padonnen; osinon: Leve kanpe, pran nat ou, mache?", bookId = 41),
        Verse(book = "Mak", chapter = 2, verseNumber = 10, text = "Enben, m'ap fè nou konnen, mwen menm, Moun Bondye voye nan lachè a, mwen gen pouvwa sou latè pou m' padonnen peche. Lè sa a, Jezi di nonm paralize a:", bookId = 41),
        Verse(book = "Mak", chapter = 2, verseNumber = 11, text = "-Mwen di ou: leve kanpe, pran nat ou, ale lakay ou.", bookId = 41),
        Verse(book = "Mak", chapter = 2, verseNumber = 12, text = "Latou, nonm lan leve kanpe, li pran nat li, li soti devan tout moun. Yo tout te sezi, yo fè lwanj Bondye; yo t'ap di: -Nou poko janm wè bagay konsa.", bookId = 41),
        Verse(book = "Mak", chapter = 2, verseNumber = 13, text = "Jezi tounen ankò bò lanmè Galile a. Yon foul moun te vin jwenn li, epi li t'ap moutre yo anpil bagay.", bookId = 41),
        Verse(book = "Mak", chapter = 2, verseNumber = 14, text = "Antan Jezi t'ap pase konsa, li wè Levi, pitit Alfe a, chita nan biwo kontribisyon an. Jezi di l' konsa: -Swiv mwen. Levi annik leve, li swiv Jezi.", bookId = 41),
        Verse(book = "Mak", chapter = 2, verseNumber = 15, text = "Pita, Jezi t'ap manje lakay Levi. Te gen anpil lòt pèseptè kontribisyon ak moun k'ap fè sa ki mal ki t'ap swiv Jezi. Tout moun sa yo te chita bò tab avè l' ansanm ak disip li yo.", bookId = 41),
        Verse(book = "Mak", chapter = 2, verseNumber = 16, text = "Kèk direktè lalwa ki te fè pati bann farizyen yo wè Jezi ap manje ak pèseptè kontribisyon yo ansanm ak moun k'ap fè sa ki mal yo. Yo mande disip li yo: -Poukisa l'ap manje ak pèseptè kontribisyon ansanm ak moun k'ap fè sa ki mal yo?", bookId = 41),
        Verse(book = "Mak", chapter = 2, verseNumber = 17, text = "Jezi tande sa, li di yo konsa: -Lè yon moun an sante, li pa bezwen dòktè. Se moun malad ki bezwen dòktè. Enben, mwen pa vin rele moun k'ap mache dwat devan Bondye yo, men moun k'ap fè sa ki mal yo.", bookId = 41),
        Verse(book = "Mak", chapter = 2, verseNumber = 18, text = "Yon jou, patizan Jan Batis yo t'ap fè jèn ansanm ak farizyen yo. Gen moun ki vin di Jezi konsa: -Poukisa patizan Jan Batis yo avèk disip farizyen yo fè jèn, epi disip pa ou yo pa fè jèn?", bookId = 41),
        Verse(book = "Mak", chapter = 2, verseNumber = 19, text = "Jezi reponn yo: -Eske zanmi yon nonm k'ap marye kapab rete san manje toutotan li la avèk yo? Non, toutotan nonm k'ap marye a la avèk yo, yo pa kapab rete san manje.", bookId = 41),
        Verse(book = "Mak", chapter = 2, verseNumber = 20, text = "Men, lè lè a va rive pou l' pa nan mitan yo ankò, se lè sa a y'a fè jèn.", bookId = 41),
        Verse(book = "Mak", chapter = 2, verseNumber = 21, text = "Pesonn pa pyese yon vye rad ak yon moso twal nèf. Si ou fè sa, moso nèf la va pati ak yon bò nan vye rad la. Lè sa a, rad la chire pi mal.", bookId = 41),
        Verse(book = "Mak", chapter = 2, verseNumber = 22, text = "Konsa tou, pesonn pa mete diven ki fenk fèt nan vye veso an po. Si ou fè sa, diven an va pete vye veso yo, epi w'ap pèdi ni diven an ni veso yo. Men, diven ki fenk fèt, sa dwe ale nan veso an po ki fenk fèt tou.", bookId = 41),
        Verse(book = "Mak", chapter = 2, verseNumber = 23, text = "Yon jou repo, Jezi t'ap pase nan yon jaden ble. Antan disip li yo t'ap mache konsa avè l', yo pran keyi kèk grap ble.", bookId = 41),
        Verse(book = "Mak", chapter = 2, verseNumber = 24, text = "Farizyen yo di li konsa: -Gade non! Poukisa disip ou yo ap fè bagay lalwa nou pa pèmèt moun fè gwo jou repo a?", bookId = 41),
        Verse(book = "Mak", chapter = 2, verseNumber = 25, text = "Jezi reponn yo: -Eske nou pa janm li sa David te fè yon lè li te bezwen manje pou li menm ak pou moun pa l' yo ki te grangou?", bookId = 41),
        Verse(book = "Mak", chapter = 2, verseNumber = 26, text = "Sa te pase sou tan Abyata te granprèt. Nou chonje? Li antre nan kay Bondye a, li manje nan pen yo te ofri bay Bondye a. Dapre lalwa nou an, se prèt yo sèlman ki gen dwa manje pen sa yo. Malgre sa, David te pran ladan yo, li te bay moun pa l' yo manje tou.", bookId = 41),
        Verse(book = "Mak", chapter = 2, verseNumber = 27, text = "Jezi di yo ankò: -Jou repo a te fèt pou moun; se pa moun ki te fèt pou jou repo a.", bookId = 41),
        Verse(book = "Mak", chapter = 2, verseNumber = 28, text = "Konsa tou, mwen menm, Moun Bondye voye nan lachè a, mwen se mèt repo a.", bookId = 41),
        Verse(book = "Mak", chapter = 3, verseNumber = 1, text = "Apre sa, Jezi tounen ankò nan sinagòg la. Te gen yon nonm ki te gen yon men pòk nan asanble a.", bookId = 41),
        Verse(book = "Mak", chapter = 3, verseNumber = 2, text = "Moun ki te la yo t'ap veye Jezi pou wè si li t'ap geri men nonm lan jou repo a, paske yo te vle akize li.", bookId = 41),
        Verse(book = "Mak", chapter = 3, verseNumber = 3, text = "Jezi di nonm men pòk la: -Leve, vin kanpe la a nan mitan nou.", bookId = 41),
        Verse(book = "Mak", chapter = 3, verseNumber = 4, text = "Epi li di moun ki t'ap gade l' yo: -Kisa lalwa nou an pèmèt moun fè jou repo a? Byen osinon mal? Sove lavi yon nonm osinon kite l' mouri? Men yo pa louvri bouch yo reponn li.", bookId = 41),
        Verse(book = "Mak", chapter = 3, verseNumber = 5, text = "Lè sa a Jezi fache, li pwonmennen je l' sou yo tout: sa te fè l' lapenn pou l' te wè jan yo te gen move santiman. Epi li di nonm lan konsa: -Lonje men ou. Nonm lan lonje men li. Latou men an geri.", bookId = 41),
        Verse(book = "Mak", chapter = 3, verseNumber = 6, text = "Menm lè a, farizyen yo soti nan sinagòg la, y' al met tèt yo ansanm ak patizan Ewòd yo pou yo wè ki jan pou yo touye Jezi.", bookId = 41),
        Verse(book = "Mak", chapter = 3, verseNumber = 7, text = "Jezi wete kò l' ak disip li yo, li ale bò lanmè Galile a. Yon gwo foul moun t'ap swiv li. Yo te soti toupatou: te gen moun Galile, moun Jide,", bookId = 41),
        Verse(book = "Mak", chapter = 3, verseNumber = 8, text = "moun lavil Jerizalèm, moun peyi Idime, moun peyi lòt bò larivyè Jouden an, moun nan vwazenaj lavil Tir ak lavil Sidon. Tout foul pèp sa a te vin jwenn li paske yo te tande tou sa l' t'ap fè.", bookId = 41),
        Verse(book = "Mak", chapter = 3, verseNumber = 9, text = "Jezi mande disip li yo pou yo pare yon kannòt pou li, pou foul la pa t' toufe l' twòp.", bookId = 41),
        Verse(book = "Mak", chapter = 3, verseNumber = 10, text = "Paske, jan li t'ap geri anpil moun, tout malad yo te vide sou li pou yo te manyen li.", bookId = 41),
        Verse(book = "Mak", chapter = 3, verseNumber = 11, text = "Chak fwa move lespri yo te wè l', yo te tonbe nan pye l' ap plede rele: -Ou se pitit Bondye a.", bookId = 41),
        Verse(book = "Mak", chapter = 3, verseNumber = 12, text = "Men Jezi te pale sevè ak move lespri yo pou yo pa t' di ki moun li te ye.", bookId = 41),
        Verse(book = "Mak", chapter = 3, verseNumber = 13, text = "Apre sa, li moute sou yon ti mòn. Li rele moun li te bezwen yo. Yo vin jwenn li.", bookId = 41),
        Verse(book = "Mak", chapter = 3, verseNumber = 14, text = "Li chwazi douz nan yo pou mache ak li. Li rele yo apòt, epi li voye yo mache bay mesaj la.", bookId = 41),
        Verse(book = "Mak", chapter = 3, verseNumber = 15, text = "Li te ba yo pouvwa pou chase mouve lespri.", bookId = 41),
        Verse(book = "Mak", chapter = 3, verseNumber = 16, text = "Men douz moun li te chwazi yo: Se te Simon (Jezi te ba li yon ti non Pyè),", bookId = 41),
        Verse(book = "Mak", chapter = 3, verseNumber = 17, text = "de pitit Zebede yo: Jak ak Jan, frè l' la. Jezi te ba yo yon ti non Boanèj, ki vle di Pitit loraj.", bookId = 41),
        Verse(book = "Mak", chapter = 3, verseNumber = 18, text = "Te gen Andre, Filip, Batèlmi, Matye, Toma, Jak, pitit Alfe a, Tade, Simon, patriyòt la,", bookId = 41),
        Verse(book = "Mak", chapter = 3, verseNumber = 19, text = "ak Jida Iskariòt, nonm ki te lage Jezi nan men lènmi li yo.", bookId = 41),
        Verse(book = "Mak", chapter = 3, verseNumber = 20, text = "Apre sa, Jezi tounen lakay li. Te sitèlman gen moun ki te sanble ankò, Jezi ak disip li yo pa t' menm gen tan pou yo te manje.", bookId = 41),
        Verse(book = "Mak", chapter = 3, verseNumber = 21, text = "Lè fanmi Jezi yo tande sa, yo soti pou yo vin chache l' paske tout moun t'ap di: -Nonm sa a fou.", bookId = 41),
        Verse(book = "Mak", chapter = 3, verseNumber = 22, text = "Dirèktè lalwa ki te desann soti Jerizalèm yo t'ap di konsa: -Li gen Bèlzeboul, gwo wa dyab la, sou li. Yo t'ap di tou: -Se chèf move lespri yo menm ki ba li pouvwa pou chase move lespri yo.", bookId = 41),
        Verse(book = "Mak", chapter = 3, verseNumber = 23, text = "Jezi rele yo, li di yo an parabòl: -Ki jan Satan fè ap chase Satan?", bookId = 41),
        Verse(book = "Mak", chapter = 3, verseNumber = 24, text = "Si yon peyi gen divizyon ladan l' pou moun yo ap goumen yonn ak lòt, peyi sa a pa la pou lontan.", bookId = 41),
        Verse(book = "Mak", chapter = 3, verseNumber = 25, text = "Si gen divizyon nan yon fanmi, fanmi sa a pa la pou lontan.", bookId = 41),
        Verse(book = "Mak", chapter = 3, verseNumber = 26, text = "Se sak fè, si Satan konbat pwòp tèt li, si gen divizyon nan peyi Satan, pouvwa Satan an pa la pou lontan. Talè konsa l'ap fini.", bookId = 41),
        Verse(book = "Mak", chapter = 3, verseNumber = 27, text = "Pesonn pa kapab antre lakay yon nonm vanyan pou piye sa l' genyen, si li pa mare nonm vanyan an anvan. Lè li fin mare l', la piye kay la.", bookId = 41),
        Verse(book = "Mak", chapter = 3, verseNumber = 28, text = "Se vre wi, sa m'ap di nou la a: Bondye va padonnen lèzòm tout peche y'a fè, ak tout move pawòl ki va soti nan bouch yo.", bookId = 41),
        Verse(book = "Mak", chapter = 3, verseNumber = 29, text = "Men, moun ki va pale mal sou Sentespri a, moun sa a p'ap janm jwenn padon, paske lè sa a l'ap fè yon peche k'ap rete pou tout tan.", bookId = 41),
        Verse(book = "Mak", chapter = 3, verseNumber = 30, text = "Jezi te pale konsa paske yo t'ap di-Li gen yon move lespri sou li.", bookId = 41),
        Verse(book = "Mak", chapter = 3, verseNumber = 31, text = "Apre sa, manman Jezi ak frè l' yo vin rive. Yo kanpe deyò a, yo fè rele li.", bookId = 41),
        Verse(book = "Mak", chapter = 3, verseNumber = 32, text = "Jezi te nan mitan yon foul moun ki te chita. Yo di l' konsa: -Men manman ou ak frè ou yo deyò a, y'ap mande pou ou.", bookId = 41),
        Verse(book = "Mak", chapter = 3, verseNumber = 33, text = "Li reponn yo: -Kilès ki manman m', kilès ki frè mwen?", bookId = 41),
        Verse(book = "Mak", chapter = 3, verseNumber = 34, text = "Epi li pwonmennen je l' sou moun ki te chita sou kote l' yo, li di konsa: -Gade: men manman m', men frè m' yo.", bookId = 41),
        Verse(book = "Mak", chapter = 3, verseNumber = 35, text = "Paske, tout moun ki fè sa Bondye mande yo fè, se moun sa yo ki frè m', ki sè m', ki manman mwen.", bookId = 41),
        Verse(book = "Mak", chapter = 4, verseNumber = 1, text = "Jezi te rekòmanse ap bay mesaj la bò lanmè Galile a ankò. Foul moun ki te sanble bò kote l' la te sitèlman anpil, li te blije moute chita nan yon kannòt ki te sou lanmè a. Tout foul moun yo menm te rete atè sou rivaj la, toupre dlo a.", bookId = 41),
        Verse(book = "Mak", chapter = 4, verseNumber = 2, text = "Li t'ap rakonte yo kèk parabòl pou l' te moutre yo anpil bagay. Li di yo konsa:", bookId = 41),
        Verse(book = "Mak", chapter = 4, verseNumber = 3, text = "-Koute! Yon nonm soti pou li al simen grenn nan jaden li.", bookId = 41),
        Verse(book = "Mak", chapter = 4, verseNumber = 4, text = "Pandan li t'ap simen grenn yo, kèk grenn tonbe bò chemen an. Zwazo vini, yo manje yo.", bookId = 41),
        Verse(book = "Mak", chapter = 4, verseNumber = 5, text = "Yon pati tonbe nan mitan wòch, kote ki pa t' gen anpil tè. Grenn sa yo leve byen vit, paske tè a pa t' fon.", bookId = 41),
        Verse(book = "Mak", chapter = 4, verseNumber = 6, text = "Men, lè solèy la chofe, li boule ti plant yo. Yo cheche paske rasen yo pa t' fon.", bookId = 41),
        Verse(book = "Mak", chapter = 4, verseNumber = 7, text = "Yon lòt pati tonbe nan mitan pye pikan. Pikan yo grandi, yo toufe bon ti plant yo, kifè yo pa t' ka donnen.", bookId = 41),
        Verse(book = "Mak", chapter = 4, verseNumber = 8, text = "Men, yon lòt pati ankò tonbe nan bon tè. Plant yo leve, yo grandi, yo donnen. Gen ladan yo ki bay trant grenn, lòt bay swasant, lòt ankò bay san (100).", bookId = 41),
        Verse(book = "Mak", chapter = 4, verseNumber = 9, text = "Apre sa, Jezi di yo konsa: -Si nou gen zòrèy poun tande, tande.", bookId = 41),
        Verse(book = "Mak", chapter = 4, verseNumber = 10, text = "Apre Jezi te fin kite gwo foul moun yo dèyè, moun ki te toupre l' yo ansanm ak douz disip li yo di li: -Esplike nou parabòl sa a non.", bookId = 41),
        Verse(book = "Mak", chapter = 4, verseNumber = 11, text = "Li di yo: -Nou menm, nou resevwa sekrè Peyi kote Bondye Wa a; men moun ki deyò yo, yo tande tout bagay an parabòl.", bookId = 41),
        Verse(book = "Mak", chapter = 4, verseNumber = 12, text = "Konsa Yo mèt gade byen gade, men yo p'ap wè. Yo mèt tande byen tande, men yo p'ap konprann, pou yo pa tounen vin jwenn Bondye, pou Bondye padonnen peche yo.", bookId = 41),
        Verse(book = "Mak", chapter = 4, verseNumber = 13, text = "Apre sa, Jezi di yo: -Nou pa konprann parabòl sa a? Ki jan n'a fè pou nou konprann tout lòt parabòl yo? Koute!", bookId = 41),
        Verse(book = "Mak", chapter = 4, verseNumber = 14, text = "Nonm k'ap simen an, se pawòl Bondye a l'ap simen.", bookId = 41),
        Verse(book = "Mak", chapter = 4, verseNumber = 15, text = "Gen moun, yo sanble ak tè bò chemen kote pawòl la tonbe a. Kou yo tande l', Satan vini, li rache pawòl ki te simen nan kè yo a.", bookId = 41),
        Verse(book = "Mak", chapter = 4, verseNumber = 16, text = "Konsa tou, gen lòt ki resevwa grenn yo tankou tè ki gen anpil wòch la. Lè yo fèk tande pawòl la, yo resevwa l' ak kè kontan.", bookId = 41),
        Verse(book = "Mak", chapter = 4, verseNumber = 17, text = "Men, yo pa kite l' pouse rasen nan kè yo. Yo pa kenbe l' pou lontan. Lè yo tonbe anba tèt chaje ak pèsekisyon akòz pawòl Bondye a, lamenm yo jwenn okazyon pou yo tonbe nan peche.", bookId = 41),
        Verse(book = "Mak", chapter = 4, verseNumber = 18, text = "Gen lòt moun ankò, yo resevwa grenn yo tankou nan mitan pye pikan: yo tande pawòl la,", bookId = 41),
        Verse(book = "Mak", chapter = 4, verseNumber = 19, text = "men, traka lavi, anvi gen lajan ak tout lòt anvi yo antre nan kè yo, toufe pawòl la. Kifè yo pa bay anyen menm.", bookId = 41),
        Verse(book = "Mak", chapter = 4, verseNumber = 20, text = "Pou fini, gen moun ki tankou bon tè a; yo tande pawòl la, yo resevwa l' epi yo donnen. Gen ladan yo ki bay trant pou yonn, lòt bay swasant pou yonn, lòt ankò bay san (100) pou yonn.", bookId = 41),
        Verse(book = "Mak", chapter = 4, verseNumber = 21, text = "Apre sa, li di yo ankò: -Yo pa limen yon lanp pou yo mete l' anba yon mamit osinon anba yon kabann, pa vre? Eske se pa sou yon etajè pou yo mete li?", bookId = 41),
        Verse(book = "Mak", chapter = 4, verseNumber = 22, text = "Nanpwen anyen ki kache ki p'ap devwale yon jou. Konsa tou, nanpwen sekrè ki p'ap parèt aklè yon lè.", bookId = 41),
        Verse(book = "Mak", chapter = 4, verseNumber = 23, text = "Si nou gen zòrèy poun tande, tande.", bookId = 41),
        Verse(book = "Mak", chapter = 4, verseNumber = 24, text = "Li di yo toujou: -Fè atansyon sa n'ap tande la a. Mezi nou sèvi pou mezire lòt moun, se li menm Bondye va pran pou mezire nou tou, ak tout degi l' sou li.", bookId = 41),
        Verse(book = "Mak", chapter = 4, verseNumber = 25, text = "Paske, moun ki genyen deja a, y'a ba li ankò. Men moun ki pa gen anyen an, y'a wete nan men l' ata ti sa l' te genyen an.", bookId = 41),
        Verse(book = "Mak", chapter = 4, verseNumber = 26, text = "Li di yo ankò: -Men ki jan sa ye nan Peyi kote Bondye Wa a. Se tankou yon nonm ki simen grenn nan jaden li.", bookId = 41),
        Verse(book = "Mak", chapter = 4, verseNumber = 27, text = "Apre sa, lannwit li dòmi, lajounen li leve fè zafè li. San l' pa konnen ki jan pa ki jan, grenn yo pouse, yo grandi.", bookId = 41),
        Verse(book = "Mak", chapter = 4, verseNumber = 28, text = "Tou sa, paske se tè a menm ki fè plant yo grandi pou yo donnen. Pou kòmanse yo pouse fèy, answit yo pouse flèch, apre sa grenn plen flèch la.", bookId = 41),
        Verse(book = "Mak", chapter = 4, verseNumber = 29, text = "Lè grenn yo mi se lè sa a nonm lan mete manchèt ladan l', paske sezon rekòt la rive.", bookId = 41),
        Verse(book = "Mak", chapter = 4, verseNumber = 30, text = "Li di yo ankò: -Kisa m' ta di Peyi kote Bondye Wa a sanble ankò? Ki parabòl mwen ta ban nou pou fè nou konprann sa li ye?", bookId = 41),
        Verse(book = "Mak", chapter = 4, verseNumber = 31, text = "Enben, li menm jan ak yon ti grenn moutad. Lè ou simen l', se yon ti grenn tou piti. Se li ki pi piti nan tout grenn ki sou latè.", bookId = 41),
        Verse(book = "Mak", chapter = 4, verseNumber = 32, text = "Men, lè ou fin simen l', li pran grandi: li depase tout plant menm kalite avè l', li pouse gwo branch. Konsa, zwazo nan syèl la ka fè nich nan lonbraj yo.", bookId = 41),
        Verse(book = "Mak", chapter = 4, verseNumber = 33, text = "Se avèk anpil parabòl konsa li t'ap ba yo mesaj li a. Li te fè l' yon jan pou yo tout te ka konprann li.", bookId = 41),
        Verse(book = "Mak", chapter = 4, verseNumber = 34, text = "Li pa t' louvri bouch li pou l' pa t' rakonte yo yon parabòl. Men, lè l' te pou kont li avèk disip li yo, li te esplike yo tout bagay.", bookId = 41),
        Verse(book = "Mak", chapter = 4, verseNumber = 35, text = "Menm jou sa a, lè solèy fin kouche, Jezi di disip li yo: -Ann janbe lòt bò lanmè a non.", bookId = 41),
        Verse(book = "Mak", chapter = 4, verseNumber = 36, text = "Se konsa disip yo te kite foul moun yo dèyè, yo pati ansanm ak Jezi nan kannòt kote li te chita a. Te gen lòt kannòt tou ki te ale avèk yo.", bookId = 41),
        Verse(book = "Mak", chapter = 4, verseNumber = 37, text = "Yon gwo van vin leve, lanm yo kòmanse antre nan kannòt la. Yon sèl kou a, kannòt la t'ap fin plen dlo.", bookId = 41),
        Verse(book = "Mak", chapter = 4, verseNumber = 38, text = "Jezi menm, lè sa a, te nan dèyè kannòt la. Li t'ap dòmi, tèt li apiye sou yon ti zòrye. Disip li yo souke l', yo di l' konsa: -Mèt, mèt, se mouri n'ap mouri wi! Sa pa di ou anyen?", bookId = 41),
        Verse(book = "Mak", chapter = 4, verseNumber = 39, text = "Jezi leve, li pale byen fò ak van an, li di: -Pe la. Li di dlo a: -Rete trankil. Latou, van an tonbe epi vin gen yon gran kalmi.", bookId = 41),
        Verse(book = "Mak", chapter = 4, verseNumber = 40, text = "Apre sa, li di yo: -Men, poukisa nou pè konsa? Nou poko gen konfyans toujou?", bookId = 41),
        Verse(book = "Mak", chapter = 4, verseNumber = 41, text = "Men disip yo te pè anpil anpil, yonn t'ap di lòt konsa: -Ki moun li ye menm, pou jouk van ak dlo lanmè a obeyi li?", bookId = 41),
        Verse(book = "Mak", chapter = 5, verseNumber = 1, text = "Jezi ak disip li yo rive lòt bò lanmè Galile a, nan peyi Jerazenyen yo.", bookId = 41),
        Verse(book = "Mak", chapter = 5, verseNumber = 2, text = "Jezi desann soti nan kannòt la. Menm lè a, yon nonm soti nan mitan tonm mò yo, li vin devan Jezi.", bookId = 41),
        Verse(book = "Mak", chapter = 5, verseNumber = 3, text = "Nonm sa a te gen yon move lespri sou li, li te pran tonm yo fè kay li. Pesonn pa t' kapab mare l', pa menm avèk chenn.", bookId = 41),
        Verse(book = "Mak", chapter = 5, verseNumber = 4, text = "Anpil fwa, yo te mete tou de pye l' yo nan yon sep an fè, yo te mare tou de menm l' yo ak yon chenn. Men, chak fwa, li te jwenn mwayen kase ni chenn lan, ni sèp la. Pesonn pa t' gen fòs ase pou donte li.", bookId = 41),
        Verse(book = "Mak", chapter = 5, verseNumber = 5, text = "Tout tan, lajounen kou lannwit, li t'ap pwonmennen nan mitan tonm yo osinon sou ti mòn yo. Li t'ap rele san rete, li t'ap matirize kò l' ak kout wòch.", bookId = 41),
        Verse(book = "Mak", chapter = 5, verseNumber = 6, text = "Li te yon bèl distans lè li wè Jezi. Li kouri, li vin mete ajenou devan li.", bookId = 41),
        Verse(book = "Mak", chapter = 5, verseNumber = 7, text = "Li pran rele byen fò, li di l' konsa: -Kisa m' gen avèk ou, Jezi, pitit Bondye ki nan syèl la? Tanpri souple, nan non Bondye, pa fè m' soufri.", bookId = 41),
        Verse(book = "Mak", chapter = 5, verseNumber = 8, text = "(Li te pale konsa, paske Jezi te pase l' lòd sa a: Move lespri, soti sou nonm lan).", bookId = 41),
        Verse(book = "Mak", chapter = 5, verseNumber = 9, text = "Lè sa a, Jezi mande li: -Ki jan ou rele? Li reponn li: -Yo rele m' Rejiman, paske nou anpil.", bookId = 41),
        Verse(book = "Mak", chapter = 5, verseNumber = 10, text = "Epi li di Jezi: -Tanpri souple, pa mete nou deyò nan peyi a.", bookId = 41),
        Verse(book = "Mak", chapter = 5, verseNumber = 11, text = "Sou ti mòn lan te gen yon bann kochon ki t'ap chache manje pou yo manje.", bookId = 41),
        Verse(book = "Mak", chapter = 5, verseNumber = 12, text = "Tout move lespri yo pran mande Jezi: -Tanpri souple, voye nou sou kochon sa yo non poun antre nan yo.", bookId = 41),
        Verse(book = "Mak", chapter = 5, verseNumber = 13, text = "Jezi bay yo pèmisyon sa a. Lè sa a, move lespri yo soti sou nonm lan, yo antre nan kochon yo. Lamenm, tout bann kochon yo pran degrengole desann bò falèz la, al neye tèt yo nan lanmè. Te gen demil (2.000) kochon konsa nan bann lan.", bookId = 41),
        Verse(book = "Mak", chapter = 5, verseNumber = 14, text = "Moun ki t'ap gade kochon yo pran kouri. Yo gaye nouvèl la nan lavil la kou andeyò. Moun soti toupatou vin wè sak te rive.", bookId = 41),
        Verse(book = "Mak", chapter = 5, verseNumber = 15, text = "Lè yo rive bò kote Jezi te ye a, yo wè nonm ki te gen rejiman move lespri sou li a. Li te chita chita l', byen abiye ak tout bon sans li sou li. Yo tout te pè.", bookId = 41),
        Verse(book = "Mak", chapter = 5, verseNumber = 16, text = "Moun ki te asiste bagay la mete rakonte lòt yo sa ki te rive nonm ak move lespri a ansanm ak kochon yo.", bookId = 41),
        Verse(book = "Mak", chapter = 5, verseNumber = 17, text = "Lè sa a, yo mande Jezi: -Tanpri souple, kite peyi a.", bookId = 41),
        Verse(book = "Mak", chapter = 5, verseNumber = 18, text = "Antan Jezi t'ap moute nan kannòt la, nonm ki te gen move lespri a mande l' pèmisyon pou li ale ave l' tou.", bookId = 41),
        Verse(book = "Mak", chapter = 5, verseNumber = 19, text = "Men Jezi pa t' kite l' ale, li di l' konsa: -Ale, tounen lakay ou, nan mitan fanmi ou yo. Rakonte yo tou sa Bondye fè pou ou, kijan li te gen pitye pou ou.", bookId = 41),
        Verse(book = "Mak", chapter = 5, verseNumber = 20, text = "Nonm lan pati, li ale nan tout rejyon yo rele Dis Vil la. Li mache fè konnen tou sa Jezi te fè pou li. Se te yon gwo sezisman pou tout moun ki te tande l' pale.", bookId = 41),
        Verse(book = "Mak", chapter = 5, verseNumber = 21, text = "Jezi tounen lòt bò lanmè a. Li annik desann soti nan kannòt la, yon foul moun gen tan sanble bò kote li. Antan li sou rivaj la,", bookId = 41),
        Verse(book = "Mak", chapter = 5, verseNumber = 22, text = "Jayiris, yonn nan chèf sinagòg yo, vin rive. Lè Jayiris wè Jezi, li lage kò l' nan pye li.", bookId = 41),
        Verse(book = "Mak", chapter = 5, verseNumber = 23, text = "Li mande Jezi: -Pitit fi m' lan prèt pou mouri. Tanpri souple, vin mete men ou sou li pou l' ka geri. vin ba l' lavi pou mwen.", bookId = 41),
        Verse(book = "Mak", chapter = 5, verseNumber = 24, text = "Jezi pati avèk li. Yon gwo foul moun t'ap swiv li. Yo te kwense l' toupatou.", bookId = 41),
        Verse(book = "Mak", chapter = 5, verseNumber = 25, text = "Men te gen yon fanm nan foul la ki te malad: li te gen pèdisyon depi douzan.", bookId = 41),
        Verse(book = "Mak", chapter = 5, verseNumber = 26, text = "Li te soufri anpil nan men plizyè dòktè, li te fin depanse tout byen li; men li pa t' jwenn okenn soulajman. Okontrè, maladi a te vin pi rèd sou li.", bookId = 41),
        Verse(book = "Mak", chapter = 5, verseNumber = 27, text = "Li te tande pale sou Jezi. Li fofile kò l' nan foul la pa dèyè Jezi, epi li manyen ke rad li.", bookId = 41),
        Verse(book = "Mak", chapter = 5, verseNumber = 28, text = "Fanm lan te di nan kè l': Si m' kapab manyen ke rad li sèlman, m'a geri.", bookId = 41),
        Verse(book = "Mak", chapter = 5, verseNumber = 29, text = "Menm lè a san an rete, epi madanm lan santi kò l' gaya.", bookId = 41),
        Verse(book = "Mak", chapter = 5, verseNumber = 30, text = "Latou, Jezi santi te gen yon fòs ki soti nan li; li vire nan mitan foul moun yo, li di konsa: -Ki moun ki manyen rad mwen an, en?", bookId = 41),
        Verse(book = "Mak", chapter = 5, verseNumber = 31, text = "Disip li yo reponn li: -Ou wè jan foul moun yo ap kwense ou, epi w'ap mande: Ki moun ki manyen ou?", bookId = 41),
        Verse(book = "Mak", chapter = 5, verseNumber = 32, text = "Men Jezi t'ap pwonmennen je l' toupatou pou wè moun ki te fè l' sa a.", bookId = 41),
        Verse(book = "Mak", chapter = 5, verseNumber = 33, text = "Fanm lan menm ki te konnen sak te rive l' t'ap tranble kou yon fèy bwa tank li te pè. Li vin lage kò l' nan pye Jezi. Li di l' tout verite a.", bookId = 41),
        Verse(book = "Mak", chapter = 5, verseNumber = 34, text = "Jezi di li: -Mafi, se konfyans ou nan Bondye ki geri ou. Ou mèt ale ak kè poze, tande. Ou geri nèt.", bookId = 41),
        Verse(book = "Mak", chapter = 5, verseNumber = 35, text = "Jezi t'ap pale toujou lè kèk mesaje soti kay chèf sinagòg la vin di li: -Pitit fi ou la mouri. Ou pa bezwen deranje Mèt la plis pase sa.", bookId = 41),
        Verse(book = "Mak", chapter = 5, verseNumber = 36, text = "Men Jezi pa t' okipe sa yo t'ap di a. Li di chèf sinagòg la: -Pa pè. Sèlman met konfyans ou nan mwen.", bookId = 41),
        Verse(book = "Mak", chapter = 5, verseNumber = 37, text = "Li pran Pyè, Jak ak Jan, frè Jak la, avèk li. Li pa t' pèmèt lòt moun swiv li.", bookId = 41),
        Verse(book = "Mak", chapter = 5, verseNumber = 38, text = "Lè yo rive kay chèf sinagòg la, Jezi wè yon bann moun ki t'ap fè gwo eskandal: genyen ki t'ap kriye; lòt menm t'ap plede rele.", bookId = 41),
        Verse(book = "Mak", chapter = 5, verseNumber = 39, text = "Li antre nan kay la, li di yo konsa: -Men pouki tout bri sa a? Pouki tout rèl sa yo? Ti fi a pa mouri. Se dòmi l'ap dòmi.", bookId = 41),
        Verse(book = "Mak", chapter = 5, verseNumber = 40, text = "Yo tonbe pase l' nan betiz. Lè sa a, li fè yo tout soti. Li pran papa ak manman pitit la ansanm ak twa disip li yo sèlman. Epi li antre nan chanm kote pitit la te ye a.", bookId = 41),
        Verse(book = "Mak", chapter = 5, verseNumber = 41, text = "Li pran men li, li di li: -Talita koum. -ki vle di: Ti fi, mwen di ou leve.", bookId = 41),
        Verse(book = "Mak", chapter = 5, verseNumber = 42, text = "Menm lè a, ti fi a leve, li pran mache, li te gen douzan. Se pa ti sezi moun yo te sezi lè yo wè sa.", bookId = 41),
        Verse(book = "Mak", chapter = 5, verseNumber = 43, text = "Men, Jezi pase yo lòd sevè pou yo pa t' kite pesonn konn sa. Apre sa, li di yo: -Bay ti fi a manje.", bookId = 41),
        Verse(book = "Mak", chapter = 6, verseNumber = 1, text = "Jezi kite kote l' te ye a, li ale nan lavil kote l' te grandi a. Disip li yo te ale avè l' tou.", bookId = 41),
        Verse(book = "Mak", chapter = 6, verseNumber = 2, text = "Lè jou repo a rive, li kòmanse moutre moun ki te nan sinagòg la anpil bagay. Foul moun ki t'ap koute l' yo te sezi anpil, yo t'ap di konsa: -Kote l' jwenn tout bagay sa yo? Kilès ki ba l' konesans sa yo? Kouman li fè fè tout mirak sa yo?", bookId = 41),
        Verse(book = "Mak", chapter = 6, verseNumber = 3, text = "Se pa ti bòs chapant pitit Mari a? Se pa frè Jak, Jòz, Jid ak Simon an? Apa tout sè l' yo la avèk nou? Se sa ki fè li te tounen pou yo yon okazyon tonbe nan peche.", bookId = 41),
        Verse(book = "Mak", chapter = 6, verseNumber = 4, text = "Lè sa a, Jezi di yo: -Yon pwofèt jwenn respè toupatou, esepte nan peyi l', lakay li ak nan fanmi li.", bookId = 41),
        Verse(book = "Mak", chapter = 6, verseNumber = 5, text = "Se konsa li pa t' kapab fè okenn mirak la, esepte pou de ou twa moun malad. Li te mete men sou tèt yo, li geri yo.", bookId = 41),
        Verse(book = "Mak", chapter = 6, verseNumber = 6, text = "Jezi te sezi wè jan yo pa t' kwè nan li. Apre sa, Jezi te mache nan tout ti bouk nan vwazinaj la. Li t'ap moutre moun yo anpil bagay.", bookId = 41),
        Verse(book = "Mak", chapter = 6, verseNumber = 7, text = "Lè sa a, Jezi rele douz disip li yo, li voye yo de pa de. Li ba yo pouvwa chase move lespri.", bookId = 41),
        Verse(book = "Mak", chapter = 6, verseNumber = 8, text = "Li pase yo lòd sa a: -Pa pran anyen pou vwayaj la, esepte yon baton. Pa pote ni pen, ni sak. Pa mete lajan nan pòch nou.", bookId = 41),
        Verse(book = "Mak", chapter = 6, verseNumber = 9, text = "Nou mèt mete sapat nan pye nou. Men, pa mete de rad sou nou.", bookId = 41),
        Verse(book = "Mak", chapter = 6, verseNumber = 10, text = "Epi li di yo ankò: -Lè nou rive nan yon lavil, rete nan yon sèl kay, kay kote y'a resevwa nou an, jouk nou pati.", bookId = 41),
        Verse(book = "Mak", chapter = 6, verseNumber = 11, text = "Men, si nou rive yon kote nou wè pesonn pa vle resevwa nou, pesonn pa vle koute nou, ale fè wout nou. Souke pousyè pye nou. Konsa, yo p'ap ka di nou pa t' avèti yo.", bookId = 41),
        Verse(book = "Mak", chapter = 6, verseNumber = 12, text = "Douz disip yo pati; y' al mache bay nouvèl la pou tout moun tounen vin jwenn Bondye.", bookId = 41),
        Verse(book = "Mak", chapter = 6, verseNumber = 13, text = "Yo te chase anpil move lespri. Yo te pase lwil sou anpil moun malad, yo te geri yo.", bookId = 41),
        Verse(book = "Mak", chapter = 6, verseNumber = 14, text = "Wa Ewòd te tande pale sou Jezi, paske yo t'ap nonmen non l' toupatou. Gen moun ki t'ap di: -Se Jan Batis ki leve pami mò yo, se poutèt sa li kapab fè tout mirak sa yo.", bookId = 41),
        Verse(book = "Mak", chapter = 6, verseNumber = 15, text = "Gen lòt ki t'ap di tou: -Se Eli. Epi gen lòt ankò ki t'ap di: -Se yon pwofèt tankou ansyen pwofèt yo.", bookId = 41),
        Verse(book = "Mak", chapter = 6, verseNumber = 16, text = "Men, lè Ewòd tande sa, li di konsa: -Se Jan wi. Mwen te fè koupe tèt li. Men, li tounen vivan ankò.", bookId = 41),
        Verse(book = "Mak", chapter = 6, verseNumber = 17, text = "Se Ewòd menm ki te voye arete Jan. Li te fè mete l' nan prizon poutèt Ewodyad. Ewòd te pran Ewodyad, madanm Filip, frè li, pou madanm li.", bookId = 41),
        Verse(book = "Mak", chapter = 6, verseNumber = 18, text = "Se konsa, Jan te di li: -Ou pa gen dwa pran madanm frè ou pou madanm ou.", bookId = 41),
        Verse(book = "Mak", chapter = 6, verseNumber = 19, text = "Ewodyad te kenbe Jan nan kè. Li te vle fè yo touye li.", bookId = 41),
        Verse(book = "Mak", chapter = 6, verseNumber = 20, text = "Men, li pa t' kapab, paske Ewòd pou tèt pa l' te gen yon krentif pou Jan. Li te konnen Jan se yon nonm dwat ki t'ap viv pou Bondye. Se sak fè li te pwoteje li. Li te renmen tande l' pale tou, menm si apre sa kè l' te boulvèse.", bookId = 41),
        Verse(book = "Mak", chapter = 6, verseNumber = 21, text = "Jou Ewodyad t'ap tann lan vin rive. Se te jou fèt Ewòd. Jou sa a, Ewòd te fè yon fèt pou tout zotobre nan gouvènman l' lan, ansanm ak gwo chèf nan lame a ak lòt grannèg nan peyi Galile a.", bookId = 41),
        Verse(book = "Mak", chapter = 6, verseNumber = 22, text = "Pitit fi Ewodyad la antre nan sal resepsyon an: li danse, li danse. Sa te fè Ewòd ak envite l' yo plezi anpil. Wa a di madmwazèl la konsa: -Mande m' nenpòt sa ou vle, m'ap ba ou li.", bookId = 41),
        Verse(book = "Mak", chapter = 6, verseNumber = 23, text = "Ewòd sèmante ba li, li di l' konsa: -Tou sa ou mande, m'ap ba ou li, te mèt mwatye nan peyi m'ap gouvènen an.", bookId = 41),
        Verse(book = "Mak", chapter = 6, verseNumber = 24, text = "Madmwazèl la soti, li al di manman li: -Kisa m' ta mande? Manman an reponn li: -Mande tèt Jan Batis.", bookId = 41),
        Verse(book = "Mak", chapter = 6, verseNumber = 25, text = "Jenn fi a prese tounen kote wa a, li fè l' demann sa a: -Mwen ta vle pou ou ban mwen tèt Jan Batis koulye a, nan yon plato.", bookId = 41),
        Verse(book = "Mak", chapter = 6, verseNumber = 26, text = "Kè wa a kase. Men, li pa t' kapab di li non ankò, akòz gwo sèman li te fin fè devan tout envite yo.", bookId = 41),
        Verse(book = "Mak", chapter = 6, verseNumber = 27, text = "Menm lè a, li voye yon gad avèk lòd pou li al chache tèt Jan Batis pote vini.", bookId = 41),
        Verse(book = "Mak", chapter = 6, verseNumber = 28, text = "Gad la koupe tèt Jan Batis nan prizon an; li pote l' vini nan yon plato. Li bay madmwazèl la tèt la; madmwazèl la menm pote l' bay manman li.", bookId = 41),
        Verse(book = "Mak", chapter = 6, verseNumber = 29, text = "Lè patizan Jan yo tande sa, yo vin pran kò a, yo mete l' nan yon kavo.", bookId = 41),
        Verse(book = "Mak", chapter = 6, verseNumber = 30, text = "Lè apòt yo tounen vin jwenn Jezi, yo rakonte l' tou sa yo te fè ak tou sa yo te di.", bookId = 41),
        Verse(book = "Mak", chapter = 6, verseNumber = 31, text = "Lè sa a, te sitèlman gen moun ki t'ap ale vini, Jezi ak disip li yo pa t' menm gen tan pou yo manje. Se poutèt sa Jezi di disip li yo: -Ann al avè m' yon kote ki pa gen moun pou nou ka pran yon ti repo.", bookId = 41),
        Verse(book = "Mak", chapter = 6, verseNumber = 32, text = "Epi, yo pati pou kont yo nan yon kannòt pou y' ale yon kote ki pa gen moun.", bookId = 41),
        Verse(book = "Mak", chapter = 6, verseNumber = 33, text = "Men, anpil moun te wè lè y' ale, yo te rekonèt yo. Se konsa, yo kouri soti nan tout bouk yo, yo gen tan rive kote Jezi taprale avèk disip li yo anvan li.", bookId = 41),
        Verse(book = "Mak", chapter = 6, verseNumber = 34, text = "Lè Jezi rive pou l' debake sot nan kannòt la, li wè tout bann moun yo. Kè l' fè l' mal pou yo, paske yo te tankou yon bann mouton san gadò. Lamenm, li tanmen esplike yo anpil bagay.", bookId = 41),
        Verse(book = "Mak", chapter = 6, verseNumber = 35, text = "Lè li te kòmanse fè ta, disip yo pwoche bò kote Jezi, yo di li: -Li fin ta, wi. Pa gen moun rete bò isit la.", bookId = 41),
        Verse(book = "Mak", chapter = 6, verseNumber = 36, text = "Voye moun yo ale non pou yo ka achte manje nan bouk yo.", bookId = 41),
        Verse(book = "Mak", chapter = 6, verseNumber = 37, text = "Jezi reponn yo: -Poukisa nou pa ba yo manje nou menm pito? Disip yo mande li: -Ou ta vle poun al achte pen pou mil (1.000) goud poun bay tout moun sa yo manje? Jezi reponn yo:", bookId = 41),
        Verse(book = "Mak", chapter = 6, verseNumber = 38, text = "-Konbe pen nou gen la a? Ale wè non. Lè yo fin jwenn konbe pen yo genyen an, yo di l' konsa: -Nou gen senk pen ak de pwason.", bookId = 41),
        Verse(book = "Mak", chapter = 6, verseNumber = 39, text = "Lè sa a, Jezi pase lòd pou disip li yo fè tout moun chita atè sou zèb la, ti gwoup bò isit, ti gwoup bò la.", bookId = 41),
        Verse(book = "Mak", chapter = 6, verseNumber = 40, text = "Moun yo menm chita pa ranje san moun, ranje senkant moun.", bookId = 41),
        Verse(book = "Mak", chapter = 6, verseNumber = 41, text = "Apre sa, Jezi pran senk pen yo ak de pwason yo, li leve je l' nan syèl la, li di Bondye mèsi. Li kase pen yo an moso, li renmèt yo bay disip li yo pou yo mache bay moun yo. Li fè menm bagay ak de pwason yo.", bookId = 41),
        Verse(book = "Mak", chapter = 6, verseNumber = 42, text = "Tout moun manje vant plen.", bookId = 41),
        Verse(book = "Mak", chapter = 6, verseNumber = 43, text = "Disip yo ranmase tout ti moso pen yo ansanm ak rès pwason yo. Yo plen douz panyen pote ale.", bookId = 41),
        Verse(book = "Mak", chapter = 6, verseNumber = 44, text = "Te gen senkmil (5.000) moun antou ki te jwenn pen pou yo manje.", bookId = 41),
        Verse(book = "Mak", chapter = 6, verseNumber = 45, text = "Touswit apre sa, Jezi fè disip li yo moute nan yon kannòt, li voye yo devan lòt bò lanmè a, nan direksyon Betsayda. Jezi menm te rete dèyè pou l' voye foul moun yo ale.", bookId = 41),
        Verse(book = "Mak", chapter = 6, verseNumber = 46, text = "Apre li fin ranvwaye yo, li al lapriyè sou yon ti mòn.", bookId = 41),
        Verse(book = "Mak", chapter = 6, verseNumber = 47, text = "Lè solèy fin kouche, kannòt la te nan mitan lanmè a toujou. Jezi te pou kont li atè.", bookId = 41),
        Verse(book = "Mak", chapter = 6, verseNumber = 48, text = "Li wè disip yo te gen anpil traka pou yo naje zaviwon yo, paske van an te kontrè pou yo. Vè twazè nan maten, Jezi pran mache sou dlo lanmè a pou li al jwenn disip yo. Li te prèt pou depase yo.", bookId = 41),
        Verse(book = "Mak", chapter = 6, verseNumber = 49, text = "Lè yo wè l' ap mache sou dlo a, yo te kwè se te yon revenan. Yo pran rele.", bookId = 41),
        Verse(book = "Mak", chapter = 6, verseNumber = 50, text = "Yo tout yo te wè li, yo tout te pè. Menm lè a, Jezi pale avèk yo, li di yo konsa: -Pran tèt nou non. Se mwen menm. Nou pa bezwen pè.", bookId = 41),
        Verse(book = "Mak", chapter = 6, verseNumber = 51, text = "Li moute bò kote yo nan kannòt la, van an vin tonbe. Se pa ti sezi disip yo te sezi.", bookId = 41),
        Verse(book = "Mak", chapter = 6, verseNumber = 52, text = "Yo pa t' konprann sans mirak pen an, paske lespri yo te bouche toujou.", bookId = 41),
        Verse(book = "Mak", chapter = 6, verseNumber = 53, text = "Yo fin travèse lanmè a, yo fè tè toupre lavil Jenezarèt. Yo mare kannòt la atè.", bookId = 41),
        Verse(book = "Mak", chapter = 6, verseNumber = 54, text = "Kou yo soti nan kannòt la, lamenm moun yo rekonèt Jezi.", bookId = 41),
        Verse(book = "Mak", chapter = 6, verseNumber = 55, text = "Pèp la kouri nan tout peyi a; yo pote malad yo tou kouche sou nat ba li kote yo tande li te ye a.", bookId = 41),
        Verse(book = "Mak", chapter = 6, verseNumber = 56, text = "Toupatou kote Jezi te rive, kit nan bouk, kit nan lavil ou andeyò, yo te mete malad yo sou plas piblik, yo te mande Jezi pou l' te kite yo manyen bò rad li ase. Tout moun ki te manyen rad li te geri.", bookId = 41),
        Verse(book = "Mak", chapter = 7, verseNumber = 1, text = "Farizyen yo ak kèk dirèktè lalwa te soti Jerizalèm. Yo sanble bò kote Jezi.", bookId = 41),
        Verse(book = "Mak", chapter = 7, verseNumber = 2, text = "Yo wè te gen nan disip li yo ki t'ap manje ak men yo tou sal, sa vle di, san yo pa t' lave men yo anvan.", bookId = 41),
        Verse(book = "Mak", chapter = 7, verseNumber = 3, text = "Farizyen yo ak tout lòt jwif yo pa t' janm manje san yo pa t' lave men yo byen lave. Nan sa, yo t'ap swiv koutim granmoun lontan yo.", bookId = 41),
        Verse(book = "Mak", chapter = 7, verseNumber = 4, text = "Lè yo soti nan mache, sa pa t' bon non plis pou yo te manje san yo pa t' pran yon beny anvan. Yo te gen yon bann lòt koutim konsa ankò yo t'ap swiv. Pa egzanp, yo te gen yon jan pou yo lave chak bagay, yon jan pou gode yo, yon jan pou krich yo, yon jan pou mamit yo, yon jan pou lave menm kabann yo.", bookId = 41),
        Verse(book = "Mak", chapter = 7, verseNumber = 5, text = "Se sak fè, farizyen yo ak dirèktè lalwa yo mande Jezi: -Poukisa disip ou yo pa swiv koutim granmoun lontan yo? Men y'ap manje ak men yo tou sal.", bookId = 41),
        Verse(book = "Mak", chapter = 7, verseNumber = 6, text = "Jezi reponn yo: -Bann ipokrit! Ezayi te gen rezon lè l' t'ap pale sou nou, jan sa ekri a: Se nan bouch pèp sa a respekte m', men kè yo byen lwen mwen.", bookId = 41),
        Verse(book = "Mak", chapter = 7, verseNumber = 7, text = "Se tan yo y'ap pèdi lè y'ap fè sèvis pou mwen. Paske nan leson yo, se pawòl lèzòm y'ap moutre moun.", bookId = 41),
        Verse(book = "Mak", chapter = 7, verseNumber = 8, text = "Jezi di yo konsa: -Nou mete kòmandman Bondye yo sou kote pou nou swiv koutim moun etabli.", bookId = 41),
        Verse(book = "Mak", chapter = 7, verseNumber = 9, text = "Li di yo tou: -Nou byen konnen jan pou nou vire kòmandman Bondye yo voye jete, pou nou ka kenbe pwòp pawòl pa nou yo.", bookId = 41),
        Verse(book = "Mak", chapter = 7, verseNumber = 10, text = "Tande byen. Moyiz di konsa: Respekte papa ou ak manman ou. Li di ankò: Si yon moun pale papa l' ak manman l' mal, se pou yo touye li.", bookId = 41),
        Verse(book = "Mak", chapter = 7, verseNumber = 11, text = "Men nou menm, nou di: Si yon moun di papa l' osinon manman l': Tou sa m' ta gen pou m' ede ou la, li kòban (sa vle di: se yon ofrann mwen mete apa pou Bondye),", bookId = 41),
        Verse(book = "Mak", chapter = 7, verseNumber = 12, text = "nan ka sa a, li pa bezwen fè anyen pou papa l' osinon manman li.", bookId = 41),
        Verse(book = "Mak", chapter = 7, verseNumber = 13, text = "Se konsa nou fè pawòl Bondye yo pase pou anyen ak pawòl pa nou n'ap transmèt yonn bay lòt. Nou fè anpil lòt bagay konsa ankò.", bookId = 41),
        Verse(book = "Mak", chapter = 7, verseNumber = 14, text = "Apre sa, Jezi rele foul moun yo vin bò kote l' ankò. Li di yo konsa: -Nou tout, tande byen sa m'ap di nou la a; manyè konprann sa.", bookId = 41),
        Verse(book = "Mak", chapter = 7, verseNumber = 15, text = "Se pa bagay deyò ki antre anndan yon moun lè l'ap manje ki kapab mete l' nan kondisyon pou li pa ka sèvi Bondye.", bookId = 41),
        Verse(book = "Mak", chapter = 7, verseNumber = 16, text = "Men, se sak sot nan kè l' ki ka mete l' nan kondisyon sa a. Si nou gen zòrèy poun tande, tande.", bookId = 41),
        Verse(book = "Mak", chapter = 7, verseNumber = 17, text = "Lè l' fin kite foul moun yo dèyè, li antre nan kay la. Disip li yo mande l' esplike yo parabòl sa a.", bookId = 41),
        Verse(book = "Mak", chapter = 7, verseNumber = 18, text = "Li di yo: -Nou menm tou, nou san konprann toujou? Nou pa konprann pawòl sa a: Tout bagay ki sot deyò antre anndan yon moun pa kapab mete l' nan kondisyon pou l' pa ka fè sèvis Bondye.", bookId = 41),
        Verse(book = "Mak", chapter = 7, verseNumber = 19, text = "Paske, manje pa antre nan kè moun. Men, sa pase nan vant; apre, yo jete sa nan latrin. (Lè l' pale konsa, Jezi fè yo konprann tout manje bon.)", bookId = 41),
        Verse(book = "Mak", chapter = 7, verseNumber = 20, text = "Li di yo ankò: -Sa ki soti nan kè yon nonm, se sa ki mete l' nan kondisyon pou l' pa ka fè sèvis Bondye.", bookId = 41),
        Verse(book = "Mak", chapter = 7, verseNumber = 21, text = "Se nan kè yon moun, se anndan li tout move lide soti: lide fè ou fè tout move bagay, li fè ou vòlè, li fè ou touye moun;", bookId = 41),
        Verse(book = "Mak", chapter = 7, verseNumber = 22, text = "li fè ou fè adiltè, li fè ou renmen lajan. Li rann ou mechan, fentè, li lage ou nan libètenaj, li ba ou gwo je, li fè ou pale moun mal, li fè ou gen lògèy, li rann ou fou.", bookId = 41),
        Verse(book = "Mak", chapter = 7, verseNumber = 23, text = "Tout move bagay sa yo, se nan kè moun sa soti, se yo ki mete yon moun nan kondisyon pou l' pa ka fè sèvis Bondye.", bookId = 41),
        Verse(book = "Mak", chapter = 7, verseNumber = 24, text = "Jezi kite kote li te ye a, li ale nan zòn ki nan vwazinaj lavil Tir la. li antre nan yon kay, li pa t' vle pesonn konnen li te la. Men, li pa t' kapab rete kache.", bookId = 41),
        Verse(book = "Mak", chapter = 7, verseNumber = 25, text = "Se konsa te gen yon fanm ki te gen yon pitit fi l' ak yon move lespri sou li. Li tande pale sou Jezi. Menm lè a, li kouri vin bò kote l', li lage kò l' nan pye Jezi.", bookId = 41),
        Verse(book = "Mak", chapter = 7, verseNumber = 26, text = "(Fanm sa a pa t' jwif, se moun peyi Siri, nan yon seksyon yo rele Fenisi.) Li te fè Jezi demann sa a: -Tanpri souple, chase move lespri ki sou pitit fi m' lan.", bookId = 41),
        Verse(book = "Mak", chapter = 7, verseNumber = 27, text = "Men Jezi di l' konsa: -Kite vant ti moun yo plen anvan; paske sa pa bon pou wete pen nan bouch timoun pou bay ti chen.", bookId = 41),
        Verse(book = "Mak", chapter = 7, verseNumber = 28, text = "Fanm lan reponn li: -Se vre wi, Mèt. Men, ti chen ki anba tab manje ti kal pen timoun jete atè.", bookId = 41),
        Verse(book = "Mak", chapter = 7, verseNumber = 29, text = "Lè sa a Jezi di li: -Poutèt pawòl sa a, ou mèt al lakay ou: move lespri a soti sou pitit fi ou la.", bookId = 41),
        Verse(book = "Mak", chapter = 7, verseNumber = 30, text = "Lè fanm lan rive lakay li, li jwenn pitit la kouche byen trankil sou kabann lan. Move lespri a te gen tan soti sou li.", bookId = 41),
        Verse(book = "Mak", chapter = 7, verseNumber = 31, text = "Jezi kite zòn lavil Tir la. Li pase lavil Sidon, li travèse nan mitan peyi Dis Vil yo; li tounen lòt bò lanmè Galile a.", bookId = 41),
        Verse(book = "Mak", chapter = 7, verseNumber = 32, text = "Yo mennen yon nonm ba li: nonm lan te soudè epi li pa t' pale byen. Yo mande Jezi pou li mete men l' sou tèt nonm lan.", bookId = 41),
        Verse(book = "Mak", chapter = 7, verseNumber = 33, text = "Men Jezi pran men nonm lan, li fè l' soti nan mitan foul moun yo, li mennen l' sou kote. Li mete dwèt li nan zòrèy nonm lan, li krache, epi li manyen lang nonm lan.", bookId = 41),
        Verse(book = "Mak", chapter = 7, verseNumber = 34, text = "Apre sa, li leve je l' nan syèl la, li bay yon soupi. Li di: -Efata! (ki vle di: Louvri!)", bookId = 41),
        Verse(book = "Mak", chapter = 7, verseNumber = 35, text = "Latou, zòrèy nonm lan louvri, lang nonm lan demare nan bouch li epi li pran pale trè byen.", bookId = 41),
        Verse(book = "Mak", chapter = 7, verseNumber = 36, text = "Jezi te mande yo tout pou yo pa t' di pesonn sa. Men plis li te defann yo pale se plis yo te mache pale bagay la.", bookId = 41),
        Verse(book = "Mak", chapter = 7, verseNumber = 37, text = "Moun yo te pi sezi ankò. Yo t'ap di: -Nonm sa a fè tout afè l' byen. Li fè soudè yo tande, li fè bèbè yo pale.", bookId = 41),
        Verse(book = "Mak", chapter = 8, verseNumber = 1, text = "Menm epòk sa a, yon gwo foul moun te sanble ankò. Yo pa t' gen anyen pou yo manje. Jezi rele disip li yo, li di yo konsa:", bookId = 41),
        Verse(book = "Mak", chapter = 8, verseNumber = 2, text = "-Kè m' fè m' mal pou moun sa yo. Sa fè twa jou depi yo la avè m', yo fin manje tou sa yo te pote.", bookId = 41),
        Verse(book = "Mak", chapter = 8, verseNumber = 3, text = "Si m' voye yo al lakay yo konsa san manje, y'a tonbe feblès nan chemen paske gen ladan yo ki soti byen lwen.", bookId = 41),
        Verse(book = "Mak", chapter = 8, verseNumber = 4, text = "Disip li yo reponn li: -Nan dezè sa a, ki bò poun jwenn pen pou plen vant tout moun sa yo?", bookId = 41),
        Verse(book = "Mak", chapter = 8, verseNumber = 5, text = "Jezi mande yo: -Konbe pen nou gen la a? Yo reponn: -Nou gen sèt pen.", bookId = 41),
        Verse(book = "Mak", chapter = 8, verseNumber = 6, text = "Lè sa a, li fè foul moun yo chita atè; li pran sèt pen yo; li di Bondye mèsi, li kase yo an moso, li renmèt yo bay disip li yo pou yo mache bay tout moun. Disip yo mache bay tout moun pen.", bookId = 41),
        Verse(book = "Mak", chapter = 8, verseNumber = 7, text = "Te gen kèk ti pwason la tou. Jezi di Bondye mèsi pou yo tou, li mande disip li yo mache bay tout foul moun yo.", bookId = 41),
        Verse(book = "Mak", chapter = 8, verseNumber = 8, text = "Tout moun te manje vant plen. Yo plen sèt panyen pote ale avèk moso ki te rete.", bookId = 41),
        Verse(book = "Mak", chapter = 8, verseNumber = 9, text = "Te gen katmil (4.000) moun konsa antou. Apre sa, Jezi voye yo ale.", bookId = 41),
        Verse(book = "Mak", chapter = 8, verseNumber = 10, text = "Touswit apre sa, li moute nan kannòt la avèk disip li yo, li ale nan yon peyi yo rele Dalmanouta.", bookId = 41),
        Verse(book = "Mak", chapter = 8, verseNumber = 11, text = "Farizyen yo vin rive. Yo tanmen diskite avèk Jezi: yo te vle pran li nan pèlen. Yo mande l' pou l' fè yon mirak ki pou moutre se Bondye ki ba li tout pouvwa sa a.", bookId = 41),
        Verse(book = "Mak", chapter = 8, verseNumber = 12, text = "Jezi bay yon gwo soupi nan kè l', li di yo konsa: -Poukisa moun alèkile yo renmen mande mirak konsa? Se vre wi sa m'ap di nou la a: yo p'ap jwenn okenn mirak.", bookId = 41),
        Verse(book = "Mak", chapter = 8, verseNumber = 13, text = "Apre sa, li vire do l' ba yo, li tounen nan kannòt la; li pati pou lòt bò lanmè a.", bookId = 41),
        Verse(book = "Mak", chapter = 8, verseNumber = 14, text = "Men, disip yo te bliye pran lòt pen: yo te gen yon sèl grenn pen avè yo nan kannòt la.", bookId = 41),
        Verse(book = "Mak", chapter = 8, verseNumber = 15, text = "Jezi ba yo lòd sa a: -Fè atansyon. Pran prekosyon nou avèk ledven farizyen yo ansanm avèk ledven Ewòd la.", bookId = 41),
        Verse(book = "Mak", chapter = 8, verseNumber = 16, text = "Disip yo pran pale pou kont yo, yonn t'ap di lòt: -Se paske nou pa gen pen kifè l' di nou sa.", bookId = 41),
        Verse(book = "Mak", chapter = 8, verseNumber = 17, text = "Jezi vin konnen sa yo t'ap di konsa. Li mande yo: -Poukisa n'ap di: se paske nou pa gen pen? Se konnen nou pa konnen? Nou poko ka konprann toujou? Se bouche lespri nou bouche konsa?", bookId = 41),
        Verse(book = "Mak", chapter = 8, verseNumber = 18, text = "Gen lè nou pa wè nan je nou? Nou pa tande nan zòrèy nou? Se bliye nou gen tan bliye?", bookId = 41),
        Verse(book = "Mak", chapter = 8, verseNumber = 19, text = "Lè m' te separe senk pen bay senkmil (5,000) moun yo, konbe panyen plen moso nou te pote ale? Yo reponn li: -Douz panyen.", bookId = 41),
        Verse(book = "Mak", chapter = 8, verseNumber = 20, text = "Jezi mande yo anko: -Lè m' te separe sèt pen bay katmil (4.000) moun yo, konbe panyen plen moso nou te pote ale? Yo reponn li: -Sèt panyen.", bookId = 41),
        Verse(book = "Mak", chapter = 8, verseNumber = 21, text = "Lè sa a li di yo: -Nou pa konprann toujou?", bookId = 41),
        Verse(book = "Mak", chapter = 8, verseNumber = 22, text = "Apre sa, y' ale Betsayda. Yo mennen yon nonm avèg bay Jezi. Yo mande li pou l' te manyen li.", bookId = 41),
        Verse(book = "Mak", chapter = 8, verseNumber = 23, text = "Jezi pran men avèg la, li mennen l' soti nan bouk la. Li pran ti gout krache, li mete nan je avèg la. Apre sa, li mete men l' sou tèt avèg la: Li mande li: -Eske ou wè kichòy?", bookId = 41),
        Verse(book = "Mak", chapter = 8, verseNumber = 24, text = "Avèg la louvri je l', li di: -Mwen wè moun k'ap mache; yo sanble pyebwa.", bookId = 41),
        Verse(book = "Mak", chapter = 8, verseNumber = 25, text = "Jezi remete men l' ankò nan je l' yo. Lè sa a, avèg la wè klè nèt. Li te geri, li te wè tout bagay klè.", bookId = 41),
        Verse(book = "Mak", chapter = 8, verseNumber = 26, text = "Jezi voye l' al lakay li, li di l' konsa: -Pa antre nan bouk la.", bookId = 41),
        Verse(book = "Mak", chapter = 8, verseNumber = 27, text = "Jezi pati apre sa avèk disip li yo; li ale nan tout bouk ki te nan rejyon Sezare Filip la. Antan yo t'ap mache, li poze yo keksyon sa a: -Ki moun yo di mwen ye en?", bookId = 41),
        Verse(book = "Mak", chapter = 8, verseNumber = 28, text = "Yo reponn li: -Gen moun ki di se Jan Batis ou ye. Gen lòt ki di ou se Eli; gen lòt ankò ki di ou se yonn nan pwofèt yo.", bookId = 41),
        Verse(book = "Mak", chapter = 8, verseNumber = 29, text = "Li mande yo ankò: -Bon, nou menm, ki moun nou di mwen ye? Pyè reponn li: -Ou se Kris la.", bookId = 41),
        Verse(book = "Mak", chapter = 8, verseNumber = 30, text = "Lè sa a, Jezi ba yo lòd byen sevè pou yo pa di pèsonn sa.", bookId = 41),
        Verse(book = "Mak", chapter = 8, verseNumber = 31, text = "Apre sa, li kòmanse di disip li yo yon bann bagay. Li di yo konsa: -Mwen menm, Moun Bondye voye nan lachè a, mwen gen pou m' soufri anpil. Chèf fanmi yo, chèf prèt yo, dirèktè lalwa yo, yo yonn p'ap vle wè mwen. Y'ap fè touye m'. Men sou twa jou, mwen gen pou m' leve soti vivan pami mò yo.", bookId = 41),
        Verse(book = "Mak", chapter = 8, verseNumber = 32, text = "Li t'ap pale konsa aklè ak yo. Pyè rele l' sou kote, li di li: -Pa pale konsa non.", bookId = 41),
        Verse(book = "Mak", chapter = 8, verseNumber = 33, text = "Men Jezi vire tèt li, li gade disip li yo. Li pale sevè ak Pyè, li di li konsa: -Wete kò ou sou mwen, Satan! Paske, lide ou pa sou sa Bondye vle, men sou sa lèzòm ta vle.", bookId = 41),
        Verse(book = "Mak", chapter = 8, verseNumber = 34, text = "Lè sa a Jezi rele foul moun yo ansanm avèk disip li yo, li di yo konsa: -Si yon moun vle mache dèyè m', se pou l' bliye tèt li, se pou l' chaje kwa l' sou zepòl li epi swiv mwen.", bookId = 41),
        Verse(book = "Mak", chapter = 8, verseNumber = 35, text = "Paske, moun ki ta vle sove lavi l' va pèdi li. Men, moun ki va pèdi lavi l' poutèt mwen ak bon nouvèl la, li va sove li.", bookId = 41),
        Verse(book = "Mak", chapter = 8, verseNumber = 36, text = "Kisa sa ta sèvi yon moun pou li ta genyen lemonn antye si l' pèdi lavi li?", bookId = 41),
        Verse(book = "Mak", chapter = 8, verseNumber = 37, text = "Ou ankò, kisa yon nonm kapab bay pou l' gen lavi?", bookId = 41),
        Verse(book = "Mak", chapter = 8, verseNumber = 38, text = "Si yon moun wont di se moun mwen li ye, si li wont pale pawòl mwen nan mitan bann moun alèkile yo ki vire do bay Bondye pou viv nan peche, enben, mwen menm tou, Moun Bondye voye nan lachè a, lè m'a tounen avèk zanj Bondye yo nan tout bèl pouvwa Papa m' lan, m'a wont pran li pou moun pa m' tou.", bookId = 41),
        Verse(book = "Mak", chapter = 9, verseNumber = 1, text = "Li di yo ankò: -Sa m'ap di nou la a, se vre wi: Nan moun ki la koulye a gen ladan yo ki p'ap mouri san yo pa wè Bondye vin pran gouvènman an nan men l' avèk pouvwa.", bookId = 41),
        Verse(book = "Mak", chapter = 9, verseNumber = 2, text = "Sis jou apre sa, Jezi pran Pyè, Jak ak Jan; li mennen yo pou kont yo sou tèt yon mòn byen wo. Figi l' chanje la devan yo;", bookId = 41),
        Verse(book = "Mak", chapter = 9, verseNumber = 3, text = "rad li vin klere tou blan. Pa gen lesivyèz sou latè ki kapab blanchi konsa.", bookId = 41),
        Verse(book = "Mak", chapter = 9, verseNumber = 4, text = "Twa disip yo wè Eli ak Moyiz parèt, yo t'ap koze avèk Jezi.", bookId = 41),
        Verse(book = "Mak", chapter = 9, verseNumber = 5, text = "Pyè pran lapawòl, li di Jezi konsa: -Mèt, sa te bon nèt pou nou te la. N'ap moute twa ti kay, yonn pou ou, yonn pou Moyiz, yonn pou Eli.", bookId = 41),
        Verse(book = "Mak", chapter = 9, verseNumber = 6, text = "Li pa t' konnen sa pou l' te di tèlman yo te pè.", bookId = 41),
        Verse(book = "Mak", chapter = 9, verseNumber = 7, text = "Yon nwaj vin kouvri yo, epi yon vwa moun soti nan nwaj la, li di: -Sa se pitit mwen renmen anpil la. Koute li.", bookId = 41),
        Verse(book = "Mak", chapter = 9, verseNumber = 8, text = "Menm lè a, disip yo vire tèt yo, yo gade adwat, yo gade agoch, men yo pa wè pesonn pase Jezi ki te pou kont li avèk yo.", bookId = 41),
        Verse(book = "Mak", chapter = 9, verseNumber = 9, text = "Antan yo t'ap desann mòn lan, Jezi pale sevè avèk yo: -Pa di pesonn sa nou sot wè la a, jouk mwen menm, Moun Bondye voye nan lachè a, m'a leve soti vivan pami mò yo.", bookId = 41),
        Verse(book = "Mak", chapter = 9, verseNumber = 10, text = "Yo te kenbe pawòl la sekrè, men yonn t'ap di lòt: -Sa sa vle di menm: leve soti vivan pami mò yo?", bookId = 41),
        Verse(book = "Mak", chapter = 9, verseNumber = 11, text = "Twa disip yo poze l' keksyon sa a: -Poukisa dirèktè lalwa yo di: Se pou Eli vin anvan.", bookId = 41),
        Verse(book = "Mak", chapter = 9, verseNumber = 12, text = "Li reponn yo: -Se vre wi. Eli gen pou l' vin anvan pou l' mete tout bagay nan lòd. Men, ki jan yo te fè ekri tou: Moun Bondye voye nan lachè a gen pou l' soufri anpil, yo p'ap manke pase l' nan betiz?", bookId = 41),
        Verse(book = "Mak", chapter = 9, verseNumber = 13, text = "Men mwen menm, mwen di nou: Eli vini deja, yo fè sa yo te vle ave l', jan sa te ekri sou li a.", bookId = 41),
        Verse(book = "Mak", chapter = 9, verseNumber = 14, text = "Lè yo rive bò kote lòt disip yo, yo wè yo nan mitan yon mas moun. Te gen kèk dirèktè lalwa la tou ki t'ap diskite avèk yo.", bookId = 41),
        Verse(book = "Mak", chapter = 9, verseNumber = 15, text = "Lè foul moun yo wè Jezi, sezisman pran yo, yo tout kouri vin di l' bonjou.", bookId = 41),
        Verse(book = "Mak", chapter = 9, verseNumber = 16, text = "Li mande disip li yo: -Sa n'ap diskite konsa?", bookId = 41),
        Verse(book = "Mak", chapter = 9, verseNumber = 17, text = "Yon nonm nan foul moun yo reponn li: -Mèt, mwen te mennen ti gason m' lan ba ou; li anba yon move lespri ki rann li bèbè.", bookId = 41),
        Verse(book = "Mak", chapter = 9, verseNumber = 18, text = "Nenpòt ki kote lespri a pran l', li fese l' atè. Lè konsa, tibway la kimen, li manje dan l', epi li vin tou rèd. Mwen te mande disip ou yo pou yo chase lespri a sot sou li, men yo pa t' kapab.", bookId = 41),
        Verse(book = "Mak", chapter = 9, verseNumber = 19, text = "Jezi di yo: -Ala moun san konfyans nan Bondye! Jouk kilè pou m' rete nan mitan nou? Jouk kilè pou m' sipòte nou? Mennen tibway la ban mwen.", bookId = 41),
        Verse(book = "Mak", chapter = 9, verseNumber = 20, text = "Yo mennen l' ba li. Kou ti nonm lan wè Jezi, move lespri a souke l' byen souke. Ti gason an tonbe atè, li woule, li kimen.", bookId = 41),
        Verse(book = "Mak", chapter = 9, verseNumber = 21, text = "Jezi mande papa a: -Depi konbe tan li konsa? Papa a reponn li: -Depi li tou piti wi.", bookId = 41),
        Verse(book = "Mak", chapter = 9, verseNumber = 22, text = "Anpil fwa menm, move lespri a jete l' nan dife, osinon nan dlo pou touye li. Men, si ou kapab fè kichòy, tanpri, ede nou. Gen pitye pou nou!", bookId = 41),
        Verse(book = "Mak", chapter = 9, verseNumber = 23, text = "Jezi di li: -Si m' kapab menm! ...Tout bagay posib wi pou moun ki met konfyans yo nan Bondye.", bookId = 41),
        Verse(book = "Mak", chapter = 9, verseNumber = 24, text = "Menm lè a, papa tibway la di byen fò: -Mwen gen konfyans nan Bondye! Men, vin ede m' pou m' sa gen plis konfyans toujou.", bookId = 41),
        Verse(book = "Mak", chapter = 9, verseNumber = 25, text = "Lè Jezi wè foul moun yo ap kouri vini, li pale sevè avèk move lespri a, li di li: -Espri bèbè, espri soudè, se mwen k'ap kòmande ou: soti sou tibway la, pa janm antre sou li ankò.", bookId = 41),
        Verse(book = "Mak", chapter = 9, verseNumber = 26, text = "Move lespri a souke tibway la byen souke; li bay yon gwo rèl, epi li soti, li ale. Ti gason an te rete tankou si l' te mouri atè a, kifè anpil moun te gen tan ap di: -Li mouri wi.", bookId = 41),
        Verse(book = "Mak", chapter = 9, verseNumber = 27, text = "Men Jezi pran men l', li fè l' leve. Lamenm, ti gason an kanpe.", bookId = 41),
        Verse(book = "Mak", chapter = 9, verseNumber = 28, text = "Antre Jezi antre nan kay la, disip yo pran l' apa, epi yo di li: -Poukisa nou pa t' kapab chase lespri sa a?", bookId = 41),
        Verse(book = "Mak", chapter = 9, verseNumber = 29, text = "Li di yo: -Se lapriyè sèlman ki pou fè kalite lespri sa a soti.", bookId = 41),
        Verse(book = "Mak", chapter = 9, verseNumber = 30, text = "Yo soti kote yo te ye a, yo travèse peyi Galile. Jezi pa t' vle moun konnen kote li te ye,", bookId = 41),
        Verse(book = "Mak", chapter = 9, verseNumber = 31, text = "paske li t'ap moutre disip li yo anpil bagay. Li di yo: -Mwen menm, Moun Bondye voye nan lachè a, mwen pral tonbe anba men lèzòm, yo pral touye mwen. Men, sou twa jou mwen gen pou m' leve soti vivan nan lanmò.", bookId = 41),
        Verse(book = "Mak", chapter = 9, verseNumber = 32, text = "Men, disip yo pa t' konprann sans pawòl sa a: epi yo te pè poze l' keksyon.", bookId = 41),
        Verse(book = "Mak", chapter = 9, verseNumber = 33, text = "Yo rive Kapènawòm. Rive li rive nan kay la, Jezi mande yo: -Kisa nou t'ap pale konsa nan chemen an?", bookId = 41),
        Verse(book = "Mak", chapter = 9, verseNumber = 34, text = "Pesonn pa louvri bouch yo reponn, paske nan chemen an, yo t'ap diskite pou konnen kilès nan yo ki te pi grannèg.", bookId = 41),
        Verse(book = "Mak", chapter = 9, verseNumber = 35, text = "Lè sa a Jezi chita, li rele douz disip yo, li di yo konsa: -Si yon moun vle pou l' nan premye plas la, fòk li mete l' dèyè nèt, fòk li sèvi tout moun.", bookId = 41),
        Verse(book = "Mak", chapter = 9, verseNumber = 36, text = "Epi li pran yon timoun piti, li mete l' nan mitan yo. Li pran timoun lan nan bra l', li di yo konsa:", bookId = 41),
        Verse(book = "Mak", chapter = 9, verseNumber = 37, text = "-Nenpòt moun ki resevwa yon timoun konsa poutèt mwen, se mwen menm menm li resevwa. Nenpòt moun ki resevwa m', se pa mwen li resevwa, men se moun ki voye m' lan li resevwa.", bookId = 41),
        Verse(book = "Mak", chapter = 9, verseNumber = 38, text = "Jan di l' konsa: -Mèt, nou te wè yon nonm ki pran non ou pou chase move lespri. Nou te vle anpeche l' fè sa, paske li pa t'ap mache avèk nou.", bookId = 41),
        Verse(book = "Mak", chapter = 9, verseNumber = 39, text = "Jezi reponn li: -Kite l' non. Paske yon moun ki pran non m' pou fè mirak pa kapab pale m' mal apre sa.", bookId = 41),
        Verse(book = "Mak", chapter = 9, verseNumber = 40, text = "Moun ki pa kont nou, se moun pa nou li ye.", bookId = 41),
        Verse(book = "Mak", chapter = 9, verseNumber = 41, text = "Sa m'ap di la a, se vre wi: nenpòt moun ki va ban nou yon gode dlo paske se moun Kris la nou ye, li pa gen dwa pèdi rekonpans li.", bookId = 41),
        Verse(book = "Mak", chapter = 9, verseNumber = 42, text = "Kanta moun ki fè yonn nan timoun sa yo ki kwè nan mwen tonbe nan peche, li ta pi bon pou li si yo te mare yon gwo wòl moulen nan kou l', voye li jete nan lanmè.", bookId = 41),
        Verse(book = "Mak", chapter = 9, verseNumber = 43, text = "Si se men ou ki pou ta fè ou tonbe nan peche, koupe l', voye l' jete. Pito ou antre nan lavi a ak yon sèl men, pase pou ou rete ak tou de men ou, apre sa pou ou al nan lanfè, kote dife a pa janm mouri.", bookId = 41),
        Verse(book = "Mak", chapter = 9, verseNumber = 44, text = "Nan lanfè, dife sa a ansanm ak vè k'ap manje kadav yo pa janm mouri.", bookId = 41),
        Verse(book = "Mak", chapter = 9, verseNumber = 45, text = "Si se pye ou ki pou ta fè ou tonbe nan peche, koupe l', voye li jete. Pito ou antre nan lavi a ak yon sèl pye, pase pou ou rete ak de pye ou, apre sa pou yo jete ou nan lanfè.", bookId = 41),
        Verse(book = "Mak", chapter = 9, verseNumber = 46, text = "Nan lanfè, dife sa a ansanm ak vè k'ap manje kadav yo pa janm mouri.", bookId = 41),
        Verse(book = "Mak", chapter = 9, verseNumber = 47, text = "Si se je ou ki pou ta fè ou tonbe nan peche, rache l' voye l' jete. Pito ou antre nan Peyi kote Bondye Wa a ak yon sèl je, pase pou ou rete ak tou de je ou, apre sa pou yo jete ou nan lanfè.", bookId = 41),
        Verse(book = "Mak", chapter = 9, verseNumber = 48, text = "La, dife a ansanm ak vè k'ap manje kadav yo pa janm mouri.", bookId = 41),
        Verse(book = "Mak", chapter = 9, verseNumber = 49, text = "Paske, tout moun ap sale ak dife.", bookId = 41),
        Verse(book = "Mak", chapter = 9, verseNumber = 50, text = "Sèl, se yon bon bagay. Men, si sèl la pèdi gou l', ak kisa poun sale l' ankò? Mete sèl nan kè nou, epi viv byen yonn ak lòt.", bookId = 41),
        Verse(book = "Mak", chapter = 10, verseNumber = 1, text = "Jezi kite kote l' te ye a; li ale nan rejyon Jide ki lòt bò larivyè Jouden an. La ankò, foul moun yo te sanble bò kote l'; li t'ap moutre yo anpil bagay, jan l' te toujou konn fè a.", bookId = 41),
        Verse(book = "Mak", chapter = 10, verseNumber = 2, text = "Kèk farizyen pwoche bò kote l' pou yo wè si yo te kapab pran l' nan pèlen. Yo mande li: -Eske lalwa nou pèmèt yon nonm kite ak madanm li?", bookId = 41),
        Verse(book = "Mak", chapter = 10, verseNumber = 3, text = "Li reponn yo: -Kisa Moyiz te ban nou lòd fè?", bookId = 41),
        Verse(book = "Mak", chapter = 10, verseNumber = 4, text = "Yo di l': -Moyiz te pèmèt pou yon nonm ekri madanm li yon papye divòs anvan pou l' kite avèk li.", bookId = 41),
        Verse(book = "Mak", chapter = 10, verseNumber = 5, text = "Lè sa a, Jezi di yo: -Moyiz te ekri kòmandman sa a pou nou paske nou gen tèt di.", bookId = 41),
        Verse(book = "Mak", chapter = 10, verseNumber = 6, text = "Men, nan konmansman, lè Bondye t'ap kreye tout bagay, Bondye te fè gason ak fi.", bookId = 41),
        Verse(book = "Mak", chapter = 10, verseNumber = 7, text = "Se poutèt sa, gason an va kite papa l' ak manman l', pou l' mete tèt ansanm ak madanm li.", bookId = 41),
        Verse(book = "Mak", chapter = 10, verseNumber = 8, text = "Tou de va fè yon sèl kò. Konsa, yo p'ap de ankò, men yo fè yon sèl.", bookId = 41),
        Verse(book = "Mak", chapter = 10, verseNumber = 9, text = "Se poutèt sa pesonn pa gen dwa separe sa Bondye mete ansanm.", bookId = 41),
        Verse(book = "Mak", chapter = 10, verseNumber = 10, text = "Lè yo antre nan kay la, disip yo poze l' keksyon ankò sou bagay sa a.", bookId = 41),
        Verse(book = "Mak", chapter = 10, verseNumber = 11, text = "Li di yo konsa: -Si yon nonm kite ak madanm li pou li al marye ak yon lòt, li fè adiltè sou madanm li.", bookId = 41),
        Verse(book = "Mak", chapter = 10, verseNumber = 12, text = "Menm jan an tou, si yon fanm kite ak mari l' pou li al marye ak yon lòt, fanm lan fè adiltè.", bookId = 41),
        Verse(book = "Mak", chapter = 10, verseNumber = 13, text = "Yo te mennen kèk timoun bay Jezi pou l' te mete men sou tèt yo. Men disip yo t'ap di moun yo pa fè sa.", bookId = 41),
        Verse(book = "Mak", chapter = 10, verseNumber = 14, text = "Lè Jezi wè sa, li pa t' kontan menm. Li di disip yo: -Kite timoun yo vin jwenn mwen non. Pa anpeche yo vini, paske Peyi kote Bondye Wa a, se pou tout moun ki tankou timoun sa yo.", bookId = 41),
        Verse(book = "Mak", chapter = 10, verseNumber = 15, text = "Sa m'ap di nou la a, se vre wi: Si yon moun pa asepte otorite Bondye a tankou yon timoun, li p'ap janm ka mete pye l' nan Peyi kote Bondye Wa a.", bookId = 41),
        Verse(book = "Mak", chapter = 10, verseNumber = 16, text = "Apre sa, li pran timoun yo nan bra l', li mete men l' sou tèt yo chak, li beni yo.", bookId = 41),
        Verse(book = "Mak", chapter = 10, verseNumber = 17, text = "Antan Jezi t'ap soti pou li al fè wout li, yon nonm kouri vini. Li lage kò l' ajenou devan Jezi, li mande li: -Bon Mèt, kisa pou m' fè pou m' resevwa lavi ki p'ap janm fini an?", bookId = 41),
        Verse(book = "Mak", chapter = 10, verseNumber = 18, text = "Jezi di li: -Poukisa ou rele m' bon? Se yon sèl bon ki genyen, se Bondye.", bookId = 41),
        Verse(book = "Mak", chapter = 10, verseNumber = 19, text = "Ou konn kòmandman yo: Piga ou touye moun; piga ou fè adiltè; piga ou vòlè; piga ou fè manti sou moun; piga ou twonpe moun; respekte papa ou ak manman ou.", bookId = 41),
        Verse(book = "Mak", chapter = 10, verseNumber = 20, text = "Li reponn Jezi: -Mèt, mwen swiv tout bagay sa yo depi m' te ti katkat.", bookId = 41),
        Verse(book = "Mak", chapter = 10, verseNumber = 21, text = "Jezi gade nonm lan, li renmen l', epi l' di li: -Yon sèl bagay ou manke: Ale vann tou sa ou genyen, separe lajan an bay pòv. Apre sa, wa gen yon richès nan syèl la. Epi vin swiv mwen.", bookId = 41),
        Verse(book = "Mak", chapter = 10, verseNumber = 22, text = "Men pawòl sa a te fè nonm lan lapenn anpil. Li vin kagou, li vire do l', li ale, paske li te gen anpil byen.", bookId = 41),
        Verse(book = "Mak", chapter = 10, verseNumber = 23, text = "Apre sa, Jezi gade disip li yo ki te bò kote l' la, li di yo: -Sa ap difisil nèt pou moun rich antre nan Peyi kote Bondye Wa a.", bookId = 41),
        Verse(book = "Mak", chapter = 10, verseNumber = 24, text = "Disip li yo te sezi anpil lè yo tande pawòl sa a. Men Jezi di yo konsa: -Mezanmi, sa ap difisil nèt pou moun antre nan peyi kote Bondye Wa a.", bookId = 41),
        Verse(book = "Mak", chapter = 10, verseNumber = 25, text = "L'ap pi fasil pou gwo bèt yo rele chamo a pase nan je yon zegwi pase pou yon moun rich antre nan peyi kote Bondye Wa a.", bookId = 41),
        Verse(book = "Mak", chapter = 10, verseNumber = 26, text = "Disip yo te pi sezi toujou, yonn t'ap di lòt: -Nan kondisyon sa a, ki moun ki ka sove?", bookId = 41),
        Verse(book = "Mak", chapter = 10, verseNumber = 27, text = "Jezi gade yo nan je, li di yo konsa: -Moun pa ka fè sa, men Bondye ka fè l', paske pa gen anyen Bondye pa ka fè.", bookId = 41),
        Verse(book = "Mak", chapter = 10, verseNumber = 28, text = "Lè sa a, Pyè di li: -Men koute non, nou kite tout bagay pou nou swiv ou.", bookId = 41),
        Verse(book = "Mak", chapter = 10, verseNumber = 29, text = "Jezi reponn li: -Sa m'ap di nou la a, se vre wi: nenpòt moun ki kite kay li, osinon frè l', osinon manman l', osinon papa l', osinon pitit li, osinon jaden l', pou sèvis mwen ak pou sèvis bon nouvèl la,", bookId = 41),
        Verse(book = "Mak", chapter = 10, verseNumber = 30, text = "moun sa a gen pou l' resevwa, depi koulye a, nan tan sa a, san (100) fwa plis pou sa l' te kite a: kay, frè, sè, manman, pitit, jaden ansanm avèk tout kalite pèsekisyon; epi nan tan k'ap vini apre sa a, li gen pou l' resevwa lavi ki p'ap janm fini an.", bookId = 41),
        Verse(book = "Mak", chapter = 10, verseNumber = 31, text = "Men, anpil nan moun ki devan yo va rete dèyè, anpil nan moun ki dèyè yo va pran devan.", bookId = 41),
        Verse(book = "Mak", chapter = 10, verseNumber = 32, text = "Lè sa a, yo te pran chemen moute lavil Jerizalèm, Jezi t'ap mache devan yo. Yon sèl kè sere pran disip yo. Tout moun ki t'ap swiv yo te pè tou. Jezi pran douz disip yo apa ankò, li kòmanse di yo sa ki te gen pou rive li.", bookId = 41),
        Verse(book = "Mak", chapter = 10, verseNumber = 33, text = "Li di yo: -Tande! Men n'ap moute lavil Jerizalèm, kote yo pral lage m', mwen menm, Moun Bondye voye nan lachè a, nan men chèf prèt yo ak nan men dirèktè lalwa yo. Yo pral kondannen m' amò, y'ap lage m' bay moun lòt nasyon yo.", bookId = 41),
        Verse(book = "Mak", chapter = 10, verseNumber = 34, text = "Moun lòt nasyon sa yo va pase m' nan rizib byen pase, y'a krache sou mwen, y'a bat mwen ak kout fwèt, apre sa y'a touye mwen. Men sou twa jou, m'a leve soti vivan nan lanmò.", bookId = 41),
        Verse(book = "Mak", chapter = 10, verseNumber = 35, text = "Apre sa, de pitit Zebede yo, Jak ak Jan, pwoche bò kot Jezi, yo di l' konsa: -Mèt, nou ta renmen ou fè sa nou pral mande ou la a pou nou.", bookId = 41),
        Verse(book = "Mak", chapter = 10, verseNumber = 36, text = "Li di yo: -Kisa nou ta vle m' fè pou nou?", bookId = 41),
        Verse(book = "Mak", chapter = 10, verseNumber = 37, text = "Yo di li: -Fè nou chita yonn sou bò dwat ou, lòt la sou bò gòch ou, lè wa nan tout bèl pouvwa ou.", bookId = 41),
        Verse(book = "Mak", chapter = 10, verseNumber = 38, text = "Jezi reponn yo: -Nou pa konnen sa n'ap mande la a. Eske nou ka bwè nan menm gode mwen pral bwè a? Eske nou ka resevwa menm batèm mwen pral resevwa a?", bookId = 41),
        Verse(book = "Mak", chapter = 10, verseNumber = 39, text = "Yo di li: -Nou kapab. Jezi reponn yo: -Se vre. n'a bwè nan menm gode mwen pral bwè a, epi n'a resevwa menm batèm mwen pral resevwa a.", bookId = 41),
        Verse(book = "Mak", chapter = 10, verseNumber = 40, text = "Men, kanta pou chita sou bò dwat osinon sou bò gòch mwen an, se pa mwen ki bay sa. Plas sa yo, Bondye rezève yo pou moun li vle.", bookId = 41),
        Verse(book = "Mak", chapter = 10, verseNumber = 41, text = "Lè dis lòt disip yo tande sa, yo pa t' manke fache sou Jak ak Jan.", bookId = 41),
        Verse(book = "Mak", chapter = 10, verseNumber = 42, text = "Jezi rele yo, li di yo konsa: -Nou konnen ki jan moun ki pase pou chèf nasyon yo trete pèp la tankou esklav; grannèg yo renmen fè moun santi jan yo gen pouvwa.", bookId = 41),
        Verse(book = "Mak", chapter = 10, verseNumber = 43, text = "Men, se pa konsa pou sa fèt nan mitan nou. Okontrè, si yonn nan nou ta vle vin grannèg, se pou l' sèvi nou tout.", bookId = 41),
        Verse(book = "Mak", chapter = 10, verseNumber = 44, text = "Si yonn nan nou ta vle chèf, se pou l' esklav nou tout.", bookId = 41),
        Verse(book = "Mak", chapter = 10, verseNumber = 45, text = "Paske, mwen menm, Moun Bondye voye nan lachè a, mwen pa vini pou moun rann mwen sèvis, men mwen vini pou m' rann moun sèvis. Wi, mwen vin bay lavi m' pou peye delivrans anpil moun.", bookId = 41),
        Verse(book = "Mak", chapter = 10, verseNumber = 46, text = "Yo te rive lavil Jeriko. Lè sa a, Jezi t'ap soti kite bouk la ansanm avèk disip li yo ak yon gwo foul moun. Te gen yon nonm avèg chita bò chemen an ki t'ap mande charite. Yo te rele l' Batime, pitit Time.", bookId = 41),
        Verse(book = "Mak", chapter = 10, verseNumber = 47, text = "Lè li tande se Jezi, moun Nazarèt la, ki t'ap pase, li pran rele: -Jezi, pitit David la, gen pitye pou mwen.", bookId = 41),
        Verse(book = "Mak", chapter = 10, verseNumber = 48, text = "Anpil moun t'ap kouri dèyè l' pou te fè l' pe bouch li, men li t'ap rele pi rèd: -Pitit David la, gen pitye pou mwen.", bookId = 41),
        Verse(book = "Mak", chapter = 10, verseNumber = 49, text = "Jezi kanpe, li di konsa: -Rele l' pou mwen. Yo rele avèg la, yo di li: -Pran kouray, leve, men li ap rele ou.", bookId = 41),
        Verse(book = "Mak", chapter = 10, verseNumber = 50, text = "Avèg la voye rad li jete, se vole li t'ap vole pou l' te vin bò kot Jezi.", bookId = 41),
        Verse(book = "Mak", chapter = 10, verseNumber = 51, text = "Jezi mande li: -Kisa ou vle m' fè pou ou? Avèg la reponn li: -Mèt, fè m' wè ankò.", bookId = 41),
        Verse(book = "Mak", chapter = 10, verseNumber = 52, text = "Jezi di li: -Ale non, se konfyans ou nan Bondye ki geri ou. Menm lè a, avèg la wè, epi li swiv Jezi nan chemen an.", bookId = 41),
        Verse(book = "Mak", chapter = 11, verseNumber = 1, text = "Yo t'ap pwoche bò Jerizalèm, bò bouk Betfaje ak Betani, yo te rive sou mòn Oliv l'a. Lè sa a, Jezi voye de nan disip li yo.", bookId = 41),
        Verse(book = "Mak", chapter = 11, verseNumber = 2, text = "Li di yo: -Ale nan bouk ki devan nou an. Lè n'a rive, n'a jwenn yon jenn ti bourik mare. Pesonn poko janm moute sou li. Lage l', mennen l' ban mwen.", bookId = 41),
        Verse(book = "Mak", chapter = 11, verseNumber = 3, text = "Nenpòt moun ki mande nou poukisa n'ap fè sa, nou mèt reponn: Se Mèt la ki bezwen li. L'ap voye ti bourik la tounen touswit.", bookId = 41),
        Verse(book = "Mak", chapter = 11, verseNumber = 4, text = "Lè disip yo ale, yo jwenn jenn ti bourik la mare deyò nan lari a, devan pòt yon kay. Yo lage li.", bookId = 41),
        Verse(book = "Mak", chapter = 11, verseNumber = 5, text = "Kèk moun ki te la di yo konsa: -Sa n'ap fè la a? Pouki n'ap lage ti bourik la?", bookId = 41),
        Verse(book = "Mak", chapter = 11, verseNumber = 6, text = "Disip yo reponn jan Jezi te di yo reponn lan. Epi moun yo kite yo ale.", bookId = 41),
        Verse(book = "Mak", chapter = 11, verseNumber = 7, text = "Yo mennen ti bourik la bay Jezi; yo mete rad sou do li, epi Jezi moute chita.", bookId = 41),
        Verse(book = "Mak", chapter = 11, verseNumber = 8, text = "Anpil moun te tann rad yo atè sou tout chemen an. Gen lòt ki te koupe branch bwa nan jaden pou mete atè nan chemen an.", bookId = 41),
        Verse(book = "Mak", chapter = 11, verseNumber = 9, text = "Ni moun ki t'ap mache devan Jezi yo, ni moun ki t'ap mache dèyè l' yo, yo tout t'ap rele byen fò: -Lwanj pou Bondye! Benediksyon pou moun ki vini nan non Mèt la.", bookId = 41),
        Verse(book = "Mak", chapter = 11, verseNumber = 10, text = "Wi, benediksyon pou gouvènman k'ap vini an, pou gouvènman wa David, papa nou. Lwanj pou Bondye jouk anwo nan syèl la!", bookId = 41),
        Verse(book = "Mak", chapter = 11, verseNumber = 11, text = "Jezi antre lavil Jerizalèm; li ale nan tanp lan. Li voye je l' sou tout bagay. Apre sa, li ale Betani avèk douz disip li yo paske li te fin ta.", bookId = 41),
        Verse(book = "Mak", chapter = 11, verseNumber = 12, text = "Nan denmen, antan yo t'ap soti Betani, Jezi te grangou.", bookId = 41),
        Verse(book = "Mak", chapter = 11, verseNumber = 13, text = "Depi byen lwen, li wè yon pye fig frans ki te plen fèy. li al wè si li ta jwenn kèk fig frans sou li. Men, lè li rive kote l', se fèy ase li jwenn, paske se pa t' sezon fig frans.", bookId = 41),
        Verse(book = "Mak", chapter = 11, verseNumber = 14, text = "Lè sa a, Jezi pale ak pye fig frans lan, li di li: -Pesonn p'ap janm manje fig ou donnen ankò. Disip yo te tande sa l' te di a.", bookId = 41),
        Verse(book = "Mak", chapter = 11, verseNumber = 15, text = "Apre sa, yo rive Jerizalèm, Jezi antre nan tanp lan. Li pran chase tout moun ki t'ap vann ak tout moun ki t'ap achte nan tanp lan. Li chavire tab moun ki t'ap chanje lajan yo ansanm ak chèz moun ki t'ap vann pijon yo.", bookId = 41),
        Verse(book = "Mak", chapter = 11, verseNumber = 16, text = "Li pa t' pèmèt pesonn travèse tanp lan ak bagay nan men yo.", bookId = 41),
        Verse(book = "Mak", chapter = 11, verseNumber = 17, text = "Li t'ap moutre moun yo anpil bagay, li di yo: -Men sa ki ekri, pa vre: y'a rele kay mwen an kay kote moun tout nasyon ka vin lapriyè. Men nou menm, nou fè l' tounen yon kachèt pou vòlò.", bookId = 41),
        Verse(book = "Mak", chapter = 11, verseNumber = 18, text = "Lè chèf prèt yo avèk dirèktè lalwa yo tande sa, yo t'ap chache yon jan pou yo fè touye l'; paske yo te vin pè l', lèfini, pawòl li t'ap moutre moun yo te aji anpil sou foul moun yo.", bookId = 41),
        Verse(book = "Mak", chapter = 11, verseNumber = 19, text = "Lè solèy fin kouche, Jezi soti kite lavil la ansanm ak disip li yo.", bookId = 41),
        Verse(book = "Mak", chapter = 11, verseNumber = 20, text = "Nan denmen maten, byen bonè, antan yo t'ap pase sou wout la, disip yo wè pye fig frans la cheche jouk nan rasen.", bookId = 41),
        Verse(book = "Mak", chapter = 11, verseNumber = 21, text = "Pyè vin chonje sak te pase. Li di Jezi konsa: -Mèt, gade pye fig frans ou te madichonnen an. Li cheche wi.", bookId = 41),
        Verse(book = "Mak", chapter = 11, verseNumber = 22, text = "Lè sa a, Jezi pran lapawòl, li di yo: -Se pou nou toujou gen konfyans nan Bondye.", bookId = 41),
        Verse(book = "Mak", chapter = 11, verseNumber = 23, text = "Sa m'ap di nou la a, se vre wi: si yon moun di mòn sa a: Wete kò ou la, al jete ou nan lanmè, si l' pa gen doutans nan kè l' menm, si l' gen fèm konviksyon sa l' di a gen pou rive, la wè l' rive vre.", bookId = 41),
        Verse(book = "Mak", chapter = 11, verseNumber = 24, text = "Se pou sa mwen di nou: Tou sa n'ap mande lè n'ap lapriyè, si nou gen fèm konviksyon nou resevwa l' deja, n'a wè sa rive vre.", bookId = 41),
        Verse(book = "Mak", chapter = 11, verseNumber = 25, text = "Lè nou kanpe poun lapriyè, si nou gen yon moun nan kè nou, padonnen l', pou Papa nou ki nan syèl la ka padonnen peche nou yo tou.", bookId = 41),
        Verse(book = "Mak", chapter = 11, verseNumber = 26, text = "Men, si nou pa padonnen lòt moun yo, Papa nou ki nan syèl la p'ap padonnen peche nou yo tou.", bookId = 41),
        Verse(book = "Mak", chapter = 11, verseNumber = 27, text = "Se konsa, yo tounen lavil Jerizalèm ankò. Pandan Jezi t'ap pwonmennen nan tanp lan, chèf prèt yo, dirèktè lalwa yo ak chèf fanmi yo te vin bò kote li.", bookId = 41),
        Verse(book = "Mak", chapter = 11, verseNumber = 28, text = "Yo di l' konsa: -Ki dwa ou genyen pou w'ap fè tout bagay sa yo? Kilès ki ba ou otorite pou fè yo?", bookId = 41),
        Verse(book = "Mak", chapter = 11, verseNumber = 29, text = "Jezi reponn yo: -Mwen pral poze nou yon sèl keksyon tou. Si nou reponn mwen, m'a di nou ak ki otorite m'ap fè bagay sa yo.", bookId = 41),
        Verse(book = "Mak", chapter = 11, verseNumber = 30, text = "Ki moun ki te voye Jan batize moun: Bondye osinon moun? Reponn mwen non.", bookId = 41),
        Verse(book = "Mak", chapter = 11, verseNumber = 31, text = "Men, yonn t'ap di lòt konsa: -Si nou reponn: Se Bondye ki voye l', la mande nou poukisa nou pa t' kwè li.", bookId = 41),
        Verse(book = "Mak", chapter = 11, verseNumber = 32, text = "Si nou reponn: Se moun ki voye l'... oum! Yo te pè pèp la, paske tout moun sa yo te pran Jan Batis pou yon bon pwofèt.", bookId = 41),
        Verse(book = "Mak", chapter = 11, verseNumber = 33, text = "Lè sa a yo reponn Jezi: -Nou pa konnen. Jezi di yo: -Enben, mwen menm tou, mwen p'ap di nou avèk ki otorite mwen fè bagay sa yo.", bookId = 41),
        Verse(book = "Mak", chapter = 12, verseNumber = 1, text = "Apre sa, Jezi pran rakonte yo yon parabòl. -Vwala, se yon nonm ki te plante yon jaden rezen. Li fèmen l' ak yon lantouraj, li fouye yon basen pou kraze rezen yo, li bati yon kay pou moun k'ap veye jaden an. Apre sa, li antann li avèk kèk moun ki pou okipe jaden an pou li. Li pati, li al nan vwayaj.", bookId = 41),
        Verse(book = "Mak", chapter = 12, verseNumber = 2, text = "Lè sezon rekòt la rive, li voye yon domestik bò kote moun ki t'ap okipe jaden an pou li. Li te voye chache pòsyon pa l' nan rekòt rezen an nan men yo.", bookId = 41),
        Verse(book = "Mak", chapter = 12, verseNumber = 3, text = "Yo mete men sou domestik la, yo bat li byen bat, epi yo voye l' tounen bay mèt jaden an san yo pa ba l' anyen.", bookId = 41),
        Verse(book = "Mak", chapter = 12, verseNumber = 4, text = "Mèt jaden an voye yon lòt domestik bò kote yo ankò. Fwa sa a menm, yo bat li nan tèt ase, epi yo joure l' byen joure.", bookId = 41),
        Verse(book = "Mak", chapter = 12, verseNumber = 5, text = "Mèt jaden an voye yon twazyèm domestik, yo touye sa a. Li voye anpil lòt ankò: gen sa yo bat, gen sa yo touye.", bookId = 41),
        Verse(book = "Mak", chapter = 12, verseNumber = 6, text = "Sèl moun mèt jaden an te rete pou l' te voye, se pitit gason li te renmen anpil la. Li voye l' an dènye bò kote yo. Li t'ap di nan kè l': Omwens y'a gen respè pou gason m' lan.", bookId = 41),
        Verse(book = "Mak", chapter = 12, verseNumber = 7, text = "Men, kiltivatè yo yonn di lòt: Men eritye a. Ann mete tèt nou ansanm. Ann touye l', konsa jaden an va vin pou nou.", bookId = 41),
        Verse(book = "Mak", chapter = 12, verseNumber = 8, text = "Yo mete men sou li, yo touye l', epi yo jete kò a deyò lòt bò jaden an.", bookId = 41),
        Verse(book = "Mak", chapter = 12, verseNumber = 9, text = "Bon! Kisa mèt jaden an gen pou l' fè ankò? La vini, la fè touye tout kiltivatè yo, epi la bay lòt moun jaden rezen an.", bookId = 41),
        Verse(book = "Mak", chapter = 12, verseNumber = 10, text = "Eske nou pa li pawòl ki ekri a? Mwen sèten nou li l' deja: Wòch moun ki t'ap bati yo te voye jete a, se li menm ki tounen wòch ki kenbe kay la.", bookId = 41),
        Verse(book = "Mak", chapter = 12, verseNumber = 11, text = "Sa se travay Mèt la. Se bèl bagay pou nou wè sa.", bookId = 41),
        Verse(book = "Mak", chapter = 12, verseNumber = 12, text = "Chèf jwif yo t'ap chache mete men sou li, paske yo te konnen byen se pou yo Jezi te di parabòl sa a. Men, yo te pè mas pèp la. Yo kite l', y' al fè wout yo.", bookId = 41),
        Verse(book = "Mak", chapter = 12, verseNumber = 13, text = "Yo te voye kèk farizyen ansanm ak kèk nan patizan Ewòd yo bò kot Jezi pou wè si yo te ka pran yon pawòl nan bouch li pou akize li.", bookId = 41),
        Verse(book = "Mak", chapter = 12, verseNumber = 14, text = "Yo vin di l' konsa: -Mèt, nou konnen ou se moun ki kare, ou pa pè pesonn, paske ou pa gade sou figi moun. Men, ou moutre chemen Bondye a jan li ye a. Manyè di nou: èske lalwa pèmèt nou peye Seza lajan kontribisyon an? Eske nou dwe peye li? Wi ou non?", bookId = 41),
        Verse(book = "Mak", chapter = 12, verseNumber = 15, text = "Men Jezi te konnen yo gen lòt lide dèyè tèt yo; li reponn yo: -Pouki n'ap chache pran m' nan pèlen konsa? Pote yon pyès lajan ban mwen pou m' gade yon bagay.", bookId = 41),
        Verse(book = "Mak", chapter = 12, verseNumber = 16, text = "Yo pote yon pyès lajan ba li. Jezi mande yo: -Pòtre ki moun ak non ki moun ki sou pyès lajan an? Yo reponn li: -Se pòtre Seza ak non Seza.", bookId = 41),
        Verse(book = "Mak", chapter = 12, verseNumber = 17, text = "Lè sa a, li di yo: -Bay Seza sa ki pou Seza, bay Bondye sa ki pou Bondye. Pawòl sa a te fè yo pi sezi ankò.", bookId = 41),
        Verse(book = "Mak", chapter = 12, verseNumber = 18, text = "Sadiseyen yo se yon gwoup jwif ki di moun mouri pa leve. Yo vin bò kot Jezi ak yon keksyon. Yo di l' konsa:", bookId = 41),
        Verse(book = "Mak", chapter = 12, verseNumber = 19, text = "-Mèt, Moyiz te ekri lòd sa a ban nou: Yon nonm ki gen frè, si l' mouri kite madanm li san pitit, frè a gen pou l' marye avèk madanm defen an pou li sa fè pitit pou frè l' ki mouri a.", bookId = 41),
        Verse(book = "Mak", chapter = 12, verseNumber = 20, text = "Se konsa, te gen sèt frè. Premye a marye, li mouri san l' pa kite pitit.", bookId = 41),
        Verse(book = "Mak", chapter = 12, verseNumber = 21, text = "Dezyèm lan marye avèk vèv la. Li mouri tou san l' pa kite pitit. Menm bagay la rive twazyèm lan tou.", bookId = 41),
        Verse(book = "Mak", chapter = 12, verseNumber = 22, text = "Konsa konsa, tout sèt frè yo marye ak fanm lan epi yo yonn pa kite pitit. Apre yo tout fin mouri, li menm tou fanm lan mouri.", bookId = 41),
        Verse(book = "Mak", chapter = 12, verseNumber = 23, text = "Lè mò yo va gen pou yo leve, madanm kilès nan yo li pral ye la a, paske li te madanm tout sèt frè yo?", bookId = 41),
        Verse(book = "Mak", chapter = 12, verseNumber = 24, text = "Jezi reponn yo: -Nou nan lerè wi. M'ap di nou poukisa: Nou pa konprann sa ki ekri a, nou pa konnen pouvwa Bondye.", bookId = 41),
        Verse(book = "Mak", chapter = 12, verseNumber = 25, text = "Lè mò yo va gen pou yo leve, fanm ak gason pa nan marye ankò. Tout moun pral viv tankou zanj Bondye nan syèl la.", bookId = 41),
        Verse(book = "Mak", chapter = 12, verseNumber = 26, text = "Pou keksyon mò yo k'ap leve vivan ankò a, èske nou pa li nan Liv Moyiz la sa Bondye te di l' bò touf bwa a: Mwen se Bondye Abraram, Bondye Izarak, Bondye Jakòb?", bookId = 41),
        Verse(book = "Mak", chapter = 12, verseNumber = 27, text = "Bondye se Bondye moun vivan li ye, li pa Bondye moun mouri. Nou wè nou nan lerè anpil, pa vre?", bookId = 41),
        Verse(book = "Mak", chapter = 12, verseNumber = 28, text = "Yonn nan dirèktè lalwa yo te tande jan yo t'ap diskite. Li wè Jezi te byen reponn sadiseyen yo. Lè sa a, li pwoche bò kote l', li mande li: -Kilès nan tout kòmandman yo ki pi konsekan an?", bookId = 41),
        Verse(book = "Mak", chapter = 12, verseNumber = 29, text = "Jezi reponn li: -Men kòmandman ki pi konsekan an: Koute, nou menm pèp Izrayèl: Mèt la, Bondye nou, se li ki sèl Mèt la.", bookId = 41),
        Verse(book = "Mak", chapter = 12, verseNumber = 30, text = "Se pou ou renmen Mèt la, Bondye ou, avèk tout kè ou, avèk tout nanm ou, avèk tout lide ou, avèk tout fòs ou.", bookId = 41),
        Verse(book = "Mak", chapter = 12, verseNumber = 31, text = "Men dezyèm kòmandman an: Se pou ou renmen frè parèy ou tankou ou renmen pwòp tèt pa ou. Pa gen lòt kòmandman ki pi konsekan pase sa yo.", bookId = 41),
        Verse(book = "Mak", chapter = 12, verseNumber = 32, text = "Lè sa a, dirèktè lalwa a di li: -Se sa menm, Mèt. Sa ou di a se vre. Met nou an se sèl Bondye ki genyen. Pa gen lòt pase li.", bookId = 41),
        Verse(book = "Mak", chapter = 12, verseNumber = 33, text = "Jan ou di a, se pou nou renmen l' ak tout kè nou, tout lespri nou, tout fòs nou, epi se pou nou renmen frè parèy nou tankou nou renmen pwòp tèt pa nou. Sa pi bon lontan pase tout ofrann n'ap boule pou Bondye ansanm ak tout lòt bèt n'ap ofri pou touye pou li.", bookId = 41),
        Verse(book = "Mak", chapter = 12, verseNumber = 34, text = "Jezi wè nonm lan te fè l' yon repons moun ki gen konprann, lè sa a li di li: -Ou menm, ou pa lwen peyi kote Bondye Wa a non. Apre sa, pesonn pa t' gen odas poze l' keksyon ankò.", bookId = 41),
        Verse(book = "Mak", chapter = 12, verseNumber = 35, text = "Pandan Jezi t'ap moutre moun yo anpil bagay nan tanp lan, li di yo: -Ki jan dirèktè lalwa yo fè di Kris la se pitit pitit David li ye?", bookId = 41),
        Verse(book = "Mak", chapter = 12, verseNumber = 36, text = "Poutan, men sa David te di (se Sentespri menm ki te fè l' di l'): Bondye te di Seyè mwen an: Chita la sou bò dwat mwen, jouk tan mwen fè lènmi ou yo tounen yon ti ban pou lonje pye ou.", bookId = 41),
        Verse(book = "Mak", chapter = 12, verseNumber = 37, text = "Si David rele Kris la Seyè, ki jan pou Kris la ta ka pitit pitit David? Yon pakèt moun t'ap koute Jezi avèk plezi.", bookId = 41),
        Verse(book = "Mak", chapter = 12, verseNumber = 38, text = "Nan sa li t'ap moutre moun yo, li di yo konsa: -Pran prekosyon nou avèk dirèktè lalwa sa yo. Yo renmen pwonmennen avèk wòb long yo, yo renmen moun di yo bonjou jouk atè lè yo sou plas piblik.", bookId = 41),
        Verse(book = "Mak", chapter = 12, verseNumber = 39, text = "Lè y' al nan sinagòg, yo chita kote pou tout moun wè yo. Nan resepsyon yo chache pi bon plas la.", bookId = 41),
        Verse(book = "Mak", chapter = 12, verseNumber = 40, text = "Se piye y'ap piye malerèz yo, an menm tan y'ap plede fè lapriyè byen long pou parèt pi bon. Kondannasyon yo pral pi rèd.", bookId = 41),
        Verse(book = "Mak", chapter = 12, verseNumber = 41, text = "Apre sa, Jezi te chita vizaviz ak bwat kote yo mete ofrann nan tanp lan. Li t'ap gade moun yo ap mete lajan ladan li. Plizyè moun rich t'ap mete anpil lajan.", bookId = 41),
        Verse(book = "Mak", chapter = 12, verseNumber = 42, text = "Yon pòv vèv vin rive tou; li mete de ti kòb ki pa t' menm fè mwatye senk kòb.", bookId = 41),
        Verse(book = "Mak", chapter = 12, verseNumber = 43, text = "Lè sa a Jezi rele disip li yo, li di yo; -Sa m'ap di nou la a, se vre wi: Pòv vèv sa a bay plis pase tout moun ki mete ofrann nan bwat la.", bookId = 41),
        Verse(book = "Mak", chapter = 12, verseNumber = 44, text = "Paske, tout moun sa yo mete sa yo pa bezwen; men li menm, nan tout mizè li, li bay tou sa l' te genyen, tout sa l' te gen pou l' viv.", bookId = 41),
        Verse(book = "Mak", chapter = 13, verseNumber = 1, text = "Antan Jezi t'ap soti nan tanp lan, yonn nan disip li yo di l' konsa: -Mèt, gade. Ala de bèl wòch! Ala yon gwo batisman!", bookId = 41),
        Verse(book = "Mak", chapter = 13, verseNumber = 2, text = "Jezi reponn li: -Ou wè gwo batisman sa a: yon lè, p'ap gen de wòch k'ap rete kanpe yonn sou lòt ladan li. Tou sa pral kraze nèt vide atè.", bookId = 41),
        Verse(book = "Mak", chapter = 13, verseNumber = 3, text = "Jezi te chita sou mòn Oliv la, vizaviz ak tanp lan. Pyè, Jak ak Andre te pou kont yo avèk li. Yo poze l' keksyon sa a:", bookId = 41),
        Verse(book = "Mak", chapter = 13, verseNumber = 4, text = "-Di nou kilè sa va rive non? Ki siy ki va fè nou konnen lè tout bagay sa a yo gen pou rive?", bookId = 41),
        Verse(book = "Mak", chapter = 13, verseNumber = 5, text = "Lè sa a Jezi pran di yo: -Atansyon pou pesonn pa twonpe nou.", bookId = 41),
        Verse(book = "Mak", chapter = 13, verseNumber = 6, text = "Paske, anpil moun va vini sou non mwen, y'a di se yo menm ki Kris la. y'a twonpe anpil moun.", bookId = 41),
        Verse(book = "Mak", chapter = 13, verseNumber = 7, text = "Lè n'a tande lagè ap fèt toupre nou, ansanm ak nouvèl lagè k'ap fèt byen lwen, nou pa bezwen pè. Fòk bagay sa yo rive. Men, se p'ap ankò lafen an sa.", bookId = 41),
        Verse(book = "Mak", chapter = 13, verseNumber = 8, text = "Yon pèp va goumen ak yon lòt pèp. Yon peyi va atake yon lòt peyi; va gen tranblemanntè divès kote. Va gen anpil grangou. Tou sa, se va tankou tranche anvan akouchman.", bookId = 41),
        Verse(book = "Mak", chapter = 13, verseNumber = 9, text = "Men, nou menm, kenbe kò nou. Y'ap trennen nou devan tribinal, y'ap bat nou nan sinagòg yo, n'ap konparèt devan chèf gouvènman ak devan wa poutèt mwen, pou nou ka sèvi m' temwen devan yo.", bookId = 41),
        Verse(book = "Mak", chapter = 13, verseNumber = 10, text = "Anvan sa, fòk yo anonse bon nouvèl la bay tout nasyon yo.", bookId = 41),
        Verse(book = "Mak", chapter = 13, verseNumber = 11, text = "Lè y'a arete nou pou mennen nou nan tribinal, pa kase tèt nou pou nou chache konnen davans sa n'a pral di; men, n'a di pawòl ki va vin nan bouch nou: paske lè sa a, se pa nou menm ki va pale, se Sentespri a ki va mete pawòl yo nan bouch nou.", bookId = 41),
        Verse(book = "Mak", chapter = 13, verseNumber = 12, text = "Frè va denonse frè pou fè touye li. Papa va denonse pitit, pitit va leve kont manman l' ak papa l', la fè touye yo.", bookId = 41),
        Verse(book = "Mak", chapter = 13, verseNumber = 13, text = "Tout moun pral rayi nou poutèt mwen; men, moun ki va kenbe fèm jouk sa kaba, se li ki va sove.", bookId = 41),
        Verse(book = "Mak", chapter = 13, verseNumber = 14, text = "Nou gen pou nou wè bagay nou pa ta renmen wè a, bagay k'ap bay gwo lapenn lan, chita kote l' pa t' dwe ye. (Se pou tout moun k'ap li sa a chache konprann.) Lè sa a, tout moun ki nan peyi Jide va blije al nan mòn.", bookId = 41),
        Verse(book = "Mak", chapter = 13, verseNumber = 15, text = "Moun ki va sou tèt kay yo va kouri met deyò san yo p'ap bezwen antre pran zafè yo.", bookId = 41),
        Verse(book = "Mak", chapter = 13, verseNumber = 16, text = "Moun ki nan jaden p'ap bezwen tounen lakay yo pou pran rechanj yo.", bookId = 41),
        Verse(book = "Mak", chapter = 13, verseNumber = 17, text = "Lè sa a, se p'ap de lapenn pou fanm ansent ak nouris yo.", bookId = 41),
        Verse(book = "Mak", chapter = 13, verseNumber = 18, text = "Lapriyè Bondye pou bagay sa yo pa rive nan tan fredi.", bookId = 41),
        Verse(book = "Mak", chapter = 13, verseNumber = 19, text = "Paske lè sa a, n'a wè yon lafliksyon moun poko janm wè, depi nan konmansman lè Bondye t'ap kreye latè jouk koulye a. p'ap janm gen yon lòt tankou l' ankò.", bookId = 41),
        Verse(book = "Mak", chapter = 13, verseNumber = 20, text = "Si Mèt la pa t' deside wete kèk jou sou jou sa yo, pesonn pa t'ap sove. Men, li wete sou jou sa yo poutèt moun li chwazi pou la ak li yo.", bookId = 41),
        Verse(book = "Mak", chapter = 13, verseNumber = 21, text = "Lè sa a, si yon moun di nou: Gade, men Kris la bò isit, osinon: Gade, men li lòt bò a, pa kwè li.", bookId = 41),
        Verse(book = "Mak", chapter = 13, verseNumber = 22, text = "Lè sa a, gen fo Kris ak fo pwofèt k'ap parèt; y'a fè mèvèy ak mirak pou twonpe ata moun Bondye chwazi yo, si yo ta kapab.", bookId = 41),
        Verse(book = "Mak", chapter = 13, verseNumber = 23, text = "Veye kò nou. Mwen tou di nou tout bagay sa yo davans.", bookId = 41),
        Verse(book = "Mak", chapter = 13, verseNumber = 24, text = "Men nan tan sa a, apre jou lafliksyon sa yo, solèy la p'ap klere ankò, lalen lan p'ap bay limyè.", bookId = 41),
        Verse(book = "Mak", chapter = 13, verseNumber = 25, text = "Zetwal yo va sot tonbe nan syèl la, pouvwa yo ki nan syèl la va tranble.", bookId = 41),
        Verse(book = "Mak", chapter = 13, verseNumber = 26, text = "Lè sa a, y'a wè m', mwen menm, Moun Bondye voye nan lachè a, ap vini sou tèt nwaj yo, avèk anpil pouvwa nan mitan yon bann bèl bagay.", bookId = 41),
        Verse(book = "Mak", chapter = 13, verseNumber = 27, text = "m'a voye zanj mwen yo nan kat kwen latè a pou sanble tout moun Bondye te chwazi yo, depi yon bout tè a jouk nan lòt bout syèl la.", bookId = 41),
        Verse(book = "Mak", chapter = 13, verseNumber = 28, text = "Pran leson sou pye fig frans lan. Kou l' kòmanse boujonnen, kou l' pouse fèy, nou konnen lete sou nou.", bookId = 41),
        Verse(book = "Mak", chapter = 13, verseNumber = 29, text = "Menm jan an tou, lè n'a wè bagay sa yo rive, nou mèt konnen Moun Bondye te voye nan lachè a toupre, li la nan papòt la.", bookId = 41),
        Verse(book = "Mak", chapter = 13, verseNumber = 30, text = "Sa m'ap di nou la a, se vre wi: gen moun k'ap viv koulye a ki p'ap gen tan mouri anvan tout bagay sa yo rive.", bookId = 41),
        Verse(book = "Mak", chapter = 13, verseNumber = 31, text = "Syèl la ak tout tè a va pase, men pawòl mwen yo p'ap janm pase.", bookId = 41),
        Verse(book = "Mak", chapter = 13, verseNumber = 32, text = "Pesonn pa konnen ni ki jou ni ki lè bagay sa yo ap rive, pa menm zanj yo ki nan syèl la, pa menm Pitit la. Sèl Papa a konn sa.", bookId = 41),
        Verse(book = "Mak", chapter = 13, verseNumber = 33, text = "Kenbe kò nou; pa kite dòmi pran nou; paske nou pa konnen ki lè lè a va rive.", bookId = 41),
        Verse(book = "Mak", chapter = 13, verseNumber = 34, text = "Se tankou lè yon nonm pati li al nan vwayaj. Li kite kay li nan men domestik yo pou yo okipe l' pou li. Li bay chak moun travay pa yo pou yo fè; li bay gadyen pòt la lòd pou l' pa dòmi.", bookId = 41),
        Verse(book = "Mak", chapter = 13, verseNumber = 35, text = "Se poutèt sa, pa kite dòmi pran nou, paske nou pa konnen ki lè mèt kay la va vini. Se ka aswè, nan mitan lannwit, lè kòk chante, osinon nan maten.", bookId = 41),
        Verse(book = "Mak", chapter = 13, verseNumber = 36, text = "Si l' rive yon lè nou pa t'ap tann li, piga li jwenn nou ap dòmi.", bookId = 41),
        Verse(book = "Mak", chapter = 13, verseNumber = 37, text = "Sa m' di nou la a, mwen di l' pou tout moun: Pa kite dòmi pran nou.", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 1, text = "Nan de jou ankò yo tapral fete fèt Delivrans lan ansanm ak fèt Pen san ledven an. Chèf prèt yo ak dirèktè lalwa yo t'ap chache mwayen pou yo arete Jezi san pesonn pa konnen, pou fè touye li.", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 2, text = "Yonn t'ap di lòt: -Nou pa kapab arete l' pandan jou fèt yo, paske sa ka kreye dezòd nan pèp la.", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 3, text = "Jezi te Betani lakay Simon, nonm ki te gen maladi lalèp la. Pandan li te chita bò tab la, yon fanm vin antre. Li t'ap pote yon ti boutèy fèt an albat. Ti boutèy la te plen yon odè bon kalite ki fèt ak yon fèy yo rele n'a ki vann byen chè. Fanm lan kase kou boutèy la, epi li vide tout odè a sou tèt Jezi.", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 4, text = "Nan moun ki te la yo, gen ladan yo ki pa t' kontan menm, yonn t'ap di lòt: -Pouki tout gaspiyay odè sa a?", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 5, text = "Yo ta kapab vann li twasan (300) goud pou pi ba pri, epi yo ta bay pòv lajan an. Yo t'ap kritike fanm lan byen fò.", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 6, text = "Men Jezi di yo: -Kite l' an repo. Pouki n'ap fè l' tout lapenn sa a? Se yon bèl bagay li fè la a pou mwen.", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 7, text = "Pòv yo, n'ap toujou genyen yo avèk nou; chak fwa nou vle, nou ka fè byen pou yo. Men, mwen menm, nou p'ap genyen m' tout tan avèk nou.", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 8, text = "Fanm lan fè sa l' te kapab. Depi davans li tou benyen kò m' pou lantèman mwen.", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 9, text = "Sa m'ap di nou la a, se vre wi: Toupatou sou latè, kote y'a anonse bon nouvèl la, y'a rakonte sa fanm lan fè la a tou pou yo pa janm bliye li.", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 10, text = "Lè sa a, Jida Iskariòt, yonn nan douz disip yo, leve, li al di chèf prèt yo li te pare pou l' te fè yo pran Jezi.", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 11, text = "Yo te kontan tande sa Jida t'ap di yo, yo pwomèt pou yo ba l' lajan. Se konsa Jida t'ap chache yon bon okazyon pou l' te ba yo Jezi.", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 12, text = "Premye jou fèt Pen san ledven an, jou yo te konn touye ti mouton pou manje Delivrans lan, disip yo di Jezi konsa: -Ki bò ou ta vle n' al pare Fèt Delivrans lan?", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 13, text = "Lè sa a, Jezi rele de nan disip li yo, li di yo: -Ale lavil la; n'a kontre yon moun k'ap pote yon krich dlo: swiv li.", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 14, text = "Kote la antre a, antre dèyè li. n'a di mèt kay la: Mèt la voye mande ou kote pyès kay pou l' manje manje Delivrans lan avèk disip li yo.", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 15, text = "La moutre nou yon gwo chanm, tou pare tou meble, anwo kay la. Se la n'a pare manje Delivrans lan pou nou tout.", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 16, text = "Disip yo pati, yo rive lavil la; yo jwenn tout bagay jan l' te di yo a. Epi yo pare manje Delivrans lan.", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 17, text = "Lè solèy fin kouche, Jezi vin rive avèk douz disip yo.", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 18, text = "Antan yo te chita bò tab la ap manje, Jezi di konsa: -Sa m'ap di nou la a, se vre wi: yonn nan nou k'ap manje avèk mwen la a pral trayi mwen.", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 19, text = "Lè sa a, kè disip yo kase; yonn apre lòt yo pran mande li: -Eske se mwen menm?", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 20, text = "Li reponn yo: -Se yonn nan nou douz la k'ap tranpe pen ansanm avè m' nan plat la.", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 21, text = "Moun Bondye voye nan lachè a pral mouri, jan sa te ekri sou li a. Men, malè pou moun k'ap trayi l' la. Li ta pi bon pou moun sa a si li pa t' janm fèt.", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 22, text = "Antan yo t'ap manje, Jezi pranpen, li di Bondye mèsi, li kase l'; li bay disip li yo, li di yo konsa: -Men, pran. Sa se kò mwen.", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 23, text = "Apre sa, li pran yon gode diven tou, li di Bondye mèsi, li pase l' ba yo, yo tout bwè ladan li.", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 24, text = "Epi Jezi di yo: -Sa se san mwen, san ki siyen kontra Bondye ap fè ak nou an, san ki koule pou anpil moun.", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 25, text = "Sa m'ap di nou la a, se vre wi: mwen p'ap janm bwè diven ankò, jouk jou m'a bwè yon diven nèf nan peyi kote Bondye Wa a.", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 26, text = "Apre yo fin chante chante fèt la, yo soti, y' ale mòn Oliv.", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 27, text = "Jezi di disip li yo: -Nou tout, nou pral kouri kite m' pou kont mwen; paske men sak te ekri: M'ap frape gadò mouton yo, epi tout mouton yo pral gaye nan bwa.", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 28, text = "Men apre, lè m'a leve soti vivan nan lanmò, mwen pral tann nou nan peyi Galile.", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 29, text = "Pyè di li: -Menm si tout moun ta kouri kite ou, mwen menm mwen p'ap janm fè sa.", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 30, text = "Jezi reponn li: -Sa m'ap di ou la a, se vre wi: Jòdi a menm, pandan lannwit sa a, anvan kòk chante de fwa, wa gen tan di twa fwa ou pa janm konnen mwen.", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 31, text = "Men, Pyè te kenbe la, li t'ap di: -Menm si m' ta dwe mouri avè ou, mwen p'ap janm di sa. Tout lòt disip yo t'ap di menm bagay la tou.", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 32, text = "Apre sa, yo rive yon kote yo rele Jetsemane. Jezi di disip li yo: -Chita la, mwen pral lapriyè pi devan.", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 33, text = "Li pran Pyè, Jak ak Jan avè li. Lamenm, li santi yon frison nan rèl do l' ak yon kè sere ki pran li.", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 34, text = "Li di yo: -Mwen gen lapenn anpil. Mwen santi se mouri mwen vle mouri. Rete la a, pa kite dòmi pran nou.", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 35, text = "Li ale yon ti kras pi lwen, li lage kò l' fas atè, li lapriyè; li mande si se te posib pou l' pa ta bezwen soufri tout soufri sa a.", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 36, text = "Li t'ap di: -O! Papa mwen, nanpwen anyen ou pa kapab fè. Tanpri souple, wete gode soufrans sa a devan je mwen. Men, fè sa ou menm ou vle a. Pa fè sa mwen menm mwen ta vle a.", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 37, text = "Li tounen bò kot disip li yo, li jwenn yo tou twa ap dòmi. Li di Pyè konsa: -Simon! W'ap dòmi? Ou pa t' kapab rete je klè menm yon ti moman?", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 38, text = "Pa dòmi, tande! Lapriyè fò pou nou pa tonbe anba tantasyon. Lespri nou byen dispoze, men se kò nou ki fèb.", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 39, text = "Li kite yo ankò, li al fè menm lapriyè a.", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 40, text = "Apre sa, li retounen. Li jwenn yo ap dòmi ankò paske yo pa t' kapab kenbe je yo louvri. Yo pa t' konn sa pou yo te reponn li.", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 41, text = "Lè l' tounen twazyèm fwa a, li di yo: -N'ap dòmi toujou? N'ap poze kò nou toujou? Sa ase koulye a. Lè a rive; men yo pral lage Moun Bondye voye nan lachè a nan men mechan yo.", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 42, text = "Leve non. Ann ale. Men moun k'ap trayi m' lan ap vini.", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 43, text = "Jezi t'ap pale toujou lè Jida, yonn nan douz disip yo, vin rive. Li te gen yon bann moun ki te gen nepe ak baton nan men yo avèk li: se chèf prèt yo ak dirèktè lalwa yo ki te voye yo avèk li.", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 44, text = "Jida, nonm ki t'ap trayi Jezi a, te gen dizon ak yo pou l' ba yo yon siyal. Li te di yo: -Moun n'a wè m' bo a se li menm n'ap chache a. Mete men sou li, mennen li ale, pa kite l' chape.", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 45, text = "Rive Jida rive, li pwoche bò kot Jezi, li di li: -Mèt! Epi li bo li.", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 46, text = "Menm lè a, moun yo mete men sou Jezi, yo arete li.", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 47, text = "Yonn nan disip yo rale nepe l', li frape domestik granprèt la; li koupe yon zòrèy li.", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 48, text = "Jezi pran lapawòl, li di yo: -Nou vin dèyè m' ak nepe, ak baton, tankou si m' te yon ansasen.", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 49, text = "Men, toulèjou mwen te la nan mitan nou, mwen t'ap pale nan tanp lan; lè sa a nou pa t' janm arete mwen. Men, tou sa pase konsa pou sa ki ekri a ka rive vre.", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 50, text = "Lè sa a tout disip yo kite l', yo pran kouri.", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 51, text = "Te gen yon jenn gason ki t'ap swiv Jezi; li te gen yon dra ase sou li. Yo mete men sou msye.", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 52, text = "Men, li lage dra a, li chape nan men yo toutouni.", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 53, text = "Yo mennen Jezi kay granprèt la. Se la tout chèf prèt yo, chèf fanmi yo ak dirèktè lalwa yo te reyini.", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 54, text = "Pyè t'ap swiv Jezi yon ti jan lwen lwen. Li antre jouk nan fon lakou kay granprèt la. Li te chita avèk gad yo bò dife a, li t'ap chofe kò li.", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 55, text = "Chèf prèt yo ak tout manm Gran Konsèy jwif yo t'ap chache yon manti pou yo te fè sou Jezi pou yo te kondannen l' amò, men yo pa t' kapab jwenn anyen menm.", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 56, text = "Anpil moun te vin fè manti sou li. Men, pawòl yo pa t' dakò.", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 57, text = "Lè sa a, kèk moun leve kanpe, yo fè manti sa a sou li:", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 58, text = "-Nou te tande l' di: m'a kraze tanp moun te fè a, epi nan twa jou m'a bati yon lòt tanp moun pa ka fè.", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 59, text = "Menm sou pwen sa a yo pa t' dakò.", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 60, text = "Lè sa a, granprèt la leve nan mitan asanble a, li poze Jezi keksyon, li di l' konsa: -Ou pa reponn anyen? Kisa mesye yo ap di sou ou konsa?", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 61, text = "Jezi pa louvri bouch li, li pa reponn anyen. Granprèt la keksyonnen li ankò, li mande l': -Eske se ou ki Kris la, Pitit Bondye ki merite lwanj la?", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 62, text = "Jezi reponn li: -Wi, se mwen menm. Nou gen pou nou wè m', mwen menm, Moun Bondye voye nan lachè a, chita sou bò dwat Bondye ki gen pouvwa a, n'a wè m' tou ap vini anwo nwaj yo nan syèl la.", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 63, text = "Lè sa a, granprèt la chire rad ki te sou li a, li di: -Sa nou bezwen temwen ankò fè?", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 64, text = "Nou sot tande jan l' pale mal sou Bondye. Sa nou di nan sa? Yo tout deklare Jezi koupab, yo di li merite lanmò.", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 65, text = "Kèk ladan yo tonbe krache sou li, yo bouche je l', yo pran ba l' koutpwen. Lèfini yo di li: -Si ou konnen di nou ki moun k'ap fè ou sa? Menm gad yo pran bay Jezi souflèt.", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 66, text = "Antan Pyè te anba nan lakou a, yonn nan sèvant granprèt la vin rive.", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 67, text = "Li wè Pyè ap chofe, li gade l' byen. Li di l' konsa: -Ou menm tou, ou te avèk Jezi, moun Nazarèt la?", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 68, text = "Pyè reponn: -Mwen pa konnen. Mwen pa konprann sa ou vle di la a. Epi Pyè soti pou li al nan pyès devan kay la. Menm lè a, yon kòk chante.", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 69, text = "Menm sèvant lan wè l' ankò. Li pran di moun ki te la yo: -Nonm sa a fè pati moun sa yo wi.", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 70, text = "Men Pyè demanti l' ankò. Yon kadè apre, moun ki te la yo di Pyè ankò: -Se vre, monchè. Ou fè pati moun sa yo, ou se moun Galile.", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 71, text = "Lè sa a, Pyè kòmanse di: -Mwen mande Bondye nenpòt bagay rive m' si m' manti: mwen pa konnen nonm n'ap pale la a.", bookId = 41),
        Verse(book = "Mak", chapter = 14, verseNumber = 72, text = "Menm lè a, kòk la chante yon dezyèm fwa. Lè sa a Pyè vin chonje pawòl Jezi te di l' la: anvan kòk chante de fwa, w'a gen tan di twa fwa ou pa janm konnen mwen. Epi li tonbe kriye.", bookId = 41),
        Verse(book = "Mak", chapter = 15, verseNumber = 1, text = "Nan granmaten, chèf prèt yo fè yon reyinyon avèk chèf fanmi yo, dirèktè lalwa yo ansanm ak tout manm Gran Konsèy jwif yo pou pran yon desizyon. Apre yo fin mare Jezi, yo mennen l' ale; yo renmèt li bay Pilat.", bookId = 41),
        Verse(book = "Mak", chapter = 15, verseNumber = 2, text = "Pilat menm mande li: -Eske ou se wa jwif yo? Jezi reponn li: -Se ou ki di li.", bookId = 41),
        Verse(book = "Mak", chapter = 15, verseNumber = 3, text = "Chèf prèt yo te depoze anpil plent sou do li.", bookId = 41),
        Verse(book = "Mak", chapter = 15, verseNumber = 4, text = "Pilat mande l' ankò: -Ou pa reponn anyen? Tande tout plent yo depoze sou do ou.", bookId = 41),
        Verse(book = "Mak", chapter = 15, verseNumber = 5, text = "Men Jezi pa reponn anyen toujou. Sa te fè Pilat sezi anpil.", bookId = 41),
        Verse(book = "Mak", chapter = 15, verseNumber = 6, text = "Pou chak fèt Delivrans Pilat te konn lage yon prizonye. Se pèp la ki te konn chwazi kilès.", bookId = 41),
        Verse(book = "Mak", chapter = 15, verseNumber = 7, text = "Te gen yon nonm yo rele Barabas; li te nan prizon ansanm ak kèk lòt ki t'ap konplote avèk li. Yo te nan prizon poutèt yon nonm yo te touye yon jou yo te pran lezam kont gouvènman an.", bookId = 41),
        Verse(book = "Mak", chapter = 15, verseNumber = 8, text = "Foul moun yo moute lakay Pilat; yo pran mande Pilat pou l' lage yon prizonye ba yo jan li te toujou fè a.", bookId = 41),
        Verse(book = "Mak", chapter = 15, verseNumber = 9, text = "Li reponn yo: -Eske nou vle mwen lage wa jwif la ban nou?", bookId = 41),
        Verse(book = "Mak", chapter = 15, verseNumber = 10, text = "Paske li te byen konnen se jalouzi ki te pouse chèf prèt yo mennen Jezi ba li.", bookId = 41),
        Verse(book = "Mak", chapter = 15, verseNumber = 11, text = "Men, chèf prèt yo pran tèt pèp la pou yo mande Pilat pou l' lage Barabas pito.", bookId = 41),
        Verse(book = "Mak", chapter = 15, verseNumber = 12, text = "Pilat pran lapawòl ankò, li di yo: -Enben, kisa nou vle m' fè avèk nonm yo rele wa jwif la?", bookId = 41),
        Verse(book = "Mak", chapter = 15, verseNumber = 13, text = "Yo rele byen fò: -Kloure l' sou yon kwa!", bookId = 41),
        Verse(book = "Mak", chapter = 15, verseNumber = 14, text = "Pilat di yo: -Men, ki move zak li fè konsa? Yo rele pi fò toujou: -Kloure l' sou yon kwa!", bookId = 41),
        Verse(book = "Mak", chapter = 15, verseNumber = 15, text = "Pilat te vle fè pèp la plezi: li lage Barabas ba yo. Apre li fin fè yo bat Jezi byen bat, li renmèt li bay sòlda yo pou y' al kloure l' sou yon kwa.", bookId = 41),
        Verse(book = "Mak", chapter = 15, verseNumber = 16, text = "Sòlda yo mennen Jezi anndan bèl lakou a (sa vle di, nan kay kòmandan an). Yo rele tout rejiman sòlda yo vini.", bookId = 41),
        Verse(book = "Mak", chapter = 15, verseNumber = 17, text = "Yo mete yon gwo rad koulè wouj violèt sou Jezi; yo trese yon kouwòn pikan, yo mete l' nan tèt li.", bookId = 41),
        Verse(book = "Mak", chapter = 15, verseNumber = 18, text = "Epi yo pran salwe l' konsa: -Bonjou, wa jwif yo!", bookId = 41),
        Verse(book = "Mak", chapter = 15, verseNumber = 19, text = "Yo ba l' kou nan tèt avèk yon baton wozo; yo krache sou li, yo mete ajenou, yo bese tèt yo devan li.", bookId = 41),
        Verse(book = "Mak", chapter = 15, verseNumber = 20, text = "Apre yo fin pase l' nan betiz kont kò yo, yo wete gwo rad la; yo mete rad pa l' sou li ankò; epi yo mennen l' ale pou yo kloure l' sou yon kwa.", bookId = 41),
        Verse(book = "Mak", chapter = 15, verseNumber = 21, text = "Te gen yon nonm yo rele Simon, moun peyi Sirèn, papa Aleksann ak Rifis. Antan Simon sa a t'ap soti nan jaden, li pase bò la, epi sòlda yo fòse msye pote kwa Jezi a.", bookId = 41),
        Verse(book = "Mak", chapter = 15, verseNumber = 22, text = "Yo mennen Jezi yon kote yo rele Gòlgota (ki vle di: Plas zo bwa tèt la).", bookId = 41),
        Verse(book = "Mak", chapter = 15, verseNumber = 23, text = "Yo te vle ba li diven melanje ak yon siwo fèt ak lami pou l' te bwè. Men, li pa pran li.", bookId = 41),
        Verse(book = "Mak", chapter = 15, verseNumber = 24, text = "Apre yo fin kloure l' sou kwa a, yo separe rad li yo ant yo: yo tire osò pou konnen sa ki t'ap soti pou yo chak.", bookId = 41),
        Verse(book = "Mak", chapter = 15, verseNumber = 25, text = "Li te nevè nan maten lè yo te kloure l' sou kwa a.", bookId = 41),
        Verse(book = "Mak", chapter = 15, verseNumber = 26, text = "Yo te bay kòz ki fè yo te kondannen l' lan sou yon ti pankat ki te ekri: Wa jwif yo!", bookId = 41),
        Verse(book = "Mak", chapter = 15, verseNumber = 27, text = "Yo te kloure de ansasen sou de lòt kwa, anmenmtan avèk Jezi, yonn sou chak bò.", bookId = 41),
        Verse(book = "Mak", chapter = 15, verseNumber = 28, text = "Se konsa pawòl ki te ekri a vin rive vre: Yo mete l' ansanm ak mechan yo.", bookId = 41),
        Verse(book = "Mak", chapter = 15, verseNumber = 29, text = "Moun ki t'ap pase bò la t'ap plede joure l'; yo t'ap fè siy sou li, yo t'ap di: -Ey! Ou menm ki te vle kraze tanp lan pou ou rebati l' nan twa jou,", bookId = 41),
        Verse(book = "Mak", chapter = 15, verseNumber = 30, text = "sove tèt ou non, desann sou kwa a.", bookId = 41),
        Verse(book = "Mak", chapter = 15, verseNumber = 31, text = "Konsa tou, chèf prèt yo ak dirèktè lalwa yo t'ap pase l' nan rizib. Yonn t'ap di lòt: -Gade! Li sove lòt moun, li pa ka sove tèt pa li!", bookId = 41),
        Verse(book = "Mak", chapter = 15, verseNumber = 32, text = "Se pou Kris la, wa pèp Izrayèl la, desann sou kwa a koulye a. Konsa n'a wè epi n'a kwè. Ata mesye ki te kloure sou lòt kwa yo t'ap joure l' tou.", bookId = 41),
        Verse(book = "Mak", chapter = 15, verseNumber = 33, text = "Vè midi konsa, vin gen yon fènwa sou tout peyi a, jouk twazè nan apremidi.", bookId = 41),
        Verse(book = "Mak", chapter = 15, verseNumber = 34, text = "Vè twazè, Jezi rele byen fò: -Eloyi, Eloyi, lema sabaktani? (ki vle di: Bondye, Bondye, poukisa ou lage m' konsa?)", bookId = 41),
        Verse(book = "Mak", chapter = 15, verseNumber = 35, text = "Nan moun ki te la yo genyen ki te tande l' pale. Yo di: -Koute. Men l'ap rele Eli.", bookId = 41),
        Verse(book = "Mak", chapter = 15, verseNumber = 36, text = "Yonn nan yo kouri, li al tranpe yon eponj nan venèg, li mete l' nan pwent yon gòl wozo, li lonje l' bò bouch Jezi ba l' bwè. Epi li di: -Rete! Ann wè si Eli va vin desann li sou kwa a!", bookId = 41),
        Verse(book = "Mak", chapter = 15, verseNumber = 37, text = "Men Jezi bay yon gwo rèl, epi li mouri.", bookId = 41),
        Verse(book = "Mak", chapter = 15, verseNumber = 38, text = "Rido ki te nan tanp lan chire an de moso depi anwo jouk anba.", bookId = 41),
        Verse(book = "Mak", chapter = 15, verseNumber = 39, text = "Te gen yon kaptenn lame kanpe anfas Jezi. Lè l' wè Jezi mouri konsa, li di: -Nonm sa a, se te pitit Bondye tout bon.", bookId = 41),
        Verse(book = "Mak", chapter = 15, verseNumber = 40, text = "Te gen kèk fanm la tou; men yo te rete lwen ap gade. Pami yo te gen Mari, moun lavil Magdala a, Mari, manman Ti Jak ak Jòz, ansanm ak Salome.", bookId = 41),
        Verse(book = "Mak", chapter = 15, verseNumber = 41, text = "Medam sa yo t'ap swiv Jezi, se yo ki t'ap okipe l' depi lè l' te nan peyi Galile. Te gen anpil lòt tou ki te moute lavil Jerizalèm ansanm ak li.", bookId = 41),
        Verse(book = "Mak", chapter = 15, verseNumber = 42, text = "Solèy te fin kouche, se te jou preparasyon jwif yo (ki vle di: lavèy jou repo a).", bookId = 41),
        Verse(book = "Mak", chapter = 15, verseNumber = 43, text = "Lè sa a Jozèf, yon moun lavil Arimate, vin rive. Se te yon manm respektab nan Gran Konsèy jwif yo. Li menm tou li t'ap tann lè Bondye t'ap vin pran gouvènman an nan men pa li. Li te gen kouraj ale devan Pilat mande kò Jezi.", bookId = 41),
        Verse(book = "Mak", chapter = 15, verseNumber = 44, text = "Men, Pilat te sezi lè l' vin konnen Jezi te gen tan mouri. Li voye rele kaptenn lan, li mande l' si Jezi te mouri depi lontan.", bookId = 41),
        Verse(book = "Mak", chapter = 15, verseNumber = 45, text = "Lè kaptenn lan fin ba li repons sèten, li bay Jozèf kò a.", bookId = 41),
        Verse(book = "Mak", chapter = 15, verseNumber = 46, text = "Jozèf achte yon bèl dra blan, li desann kò Jezi sou kwa a, li vlope l' nan dra a, epi li mete l' nan yon kavo yo te fouye nan wòch la. Apre sa, li woule yon gwo wòch devan bouch kavo a.", bookId = 41),
        Verse(book = "Mak", chapter = 15, verseNumber = 47, text = "Mari, moun lavil Magdala a, ansanm ak Mari, manman Jòz, t'ap gade kote yo mete kò a.", bookId = 41),
        Verse(book = "Mak", chapter = 16, verseNumber = 1, text = "Lè jou repo a te fin pase, Mari, moun lavil Magdala a, Mari, manman Jak, ansanm ak Salome, te achte medikaman pou y' al benyen kò Jezi.", bookId = 41),
        Verse(book = "Mak", chapter = 16, verseNumber = 2, text = "Nan dimanch maten byen bonè, solèy te fèk ap leve, medam yo ale nan kavo a.", bookId = 41),
        Verse(book = "Mak", chapter = 16, verseNumber = 3, text = "Yonn t'ap di lòt: -Ki moun ki pral woule wòch ki devan bouch kavo a pou nou?", bookId = 41),
        Verse(book = "Mak", chapter = 16, verseNumber = 4, text = "Lè yo leve je yo, yo wè yo te gen tan woule wòch la sou kote. E se te yon gwo wòch.", bookId = 41),
        Verse(book = "Mak", chapter = 16, verseNumber = 5, text = "Yo antre nan kavo a, yo wè yon jenn gason chita sou bò dwat la; li te gen yon wòb tou blan sou li. Yo te sezi, yo te pè.", bookId = 41),
        Verse(book = "Mak", chapter = 16, verseNumber = 6, text = "Men, jenn gason an di yo: -Nou pa bezwen pè: N'ap chache Jezi, moun Nazarèt yo te kloure sou kwa a? Enben, li leve soti vivan nan lanmò, li pa isit la. Gade. Men kote yo te mete l' la.", bookId = 41),
        Verse(book = "Mak", chapter = 16, verseNumber = 7, text = "Ale di disip li yo ansanm ak Pyè, li al tann yo nan peyi Galile. Se la y'a wè l', jan l' te di yo a.", bookId = 41),
        Verse(book = "Mak", chapter = 16, verseNumber = 8, text = "Medam yo soti nan kavo a, yo pran kouri ale. Yo t'ap tranble kou fèy bwa, yo te pè anpil. Yo pa di pesonn anyen tèlman yo te pè.", bookId = 41),
        Verse(book = "Mak", chapter = 16, verseNumber = 9, text = "Nan dimanch maten, Jezi te leve soti vivan nan lanmò. Premye moun li te fè wè li, se te Mari, moun lavil Magdala a. (Se sou li Jezi te wete sèt move lespri.)", bookId = 41),
        Verse(book = "Mak", chapter = 16, verseNumber = 10, text = "Mari al pote nouvèl la bay moun ki te konn ak Jezi yo. Yo te nan lapenn anpil, yo t'ap kriye.", bookId = 41),
        Verse(book = "Mak", chapter = 16, verseNumber = 11, text = "Men, yo pa t' vle kwè Mari, lè l' te di yo: -Jezi vivan, mwen wè l' ak de je mwen.", bookId = 41),
        Verse(book = "Mak", chapter = 16, verseNumber = 12, text = "Apre sa, Jezi te parèt yon lòt jan ankò devan de nan disip yo, antan yo te nan chemen pou ale andeyò.", bookId = 41),
        Verse(book = "Mak", chapter = 16, verseNumber = 13, text = "Yo tounen sou chemen yo vin fè lòt yo konn sa. Men, lòt yo pa t' ankò vle kwè toujou.", bookId = 41),
        Verse(book = "Mak", chapter = 16, verseNumber = 14, text = "Pita, Jezi parèt devan tout onz disip yo yon lè yo t'ap manje. Li repwoche yo dèske yo pa t' gen konfyans, yo t'ap fè tèt di toujou, yo pa t' kwè moun ki te wè l' yo apre li te leve soti vivan pami mò yo.", bookId = 41),
        Verse(book = "Mak", chapter = 16, verseNumber = 15, text = "Epi li di yo: -Ale toupatou sou latè, anonse Bon Nouvèl la bay tout moun.", bookId = 41),
        Verse(book = "Mak", chapter = 16, verseNumber = 16, text = "Moun ki kwè epi ki resevwa batèm va delivre. Men, moun ki pa kwè va kondannen.", bookId = 41),
        Verse(book = "Mak", chapter = 16, verseNumber = 17, text = "Moun ki kwè va fè anpil mirak; y'a chase move lespri nan non mwen, y'a pale lòt lang.", bookId = 41),
        Verse(book = "Mak", chapter = 16, verseNumber = 18, text = "Yo ta mèt kenbe sèpan, yo ta mèt bwè pwazon, anyen p'ap rive yo. y'a mete men sou tèt moun malad, moun malad yo va geri.", bookId = 41),
        Verse(book = "Mak", chapter = 16, verseNumber = 19, text = "Apre Seyè Jezi te fin pale ak yo konsa, li moute nan syèl, li al chita sou bò dwat Bondye.", bookId = 41),
        Verse(book = "Mak", chapter = 16, verseNumber = 20, text = "Disip yo pati, y' al anonse Bon Nouvèl la toupatou. Seyè a t'ap travay ansanm ak yo: Anmenmtan li t'ap fè anpil mirak tou pou moutre sa yo t'ap di a se vre.", bookId = 41)
    )
}
